  function pksCell(lane, col) {
    if (lane < 0 || lane >= PKS_LANES || col < 0 || col >= PKS_COLS) return null;
    var d = pksCellScratch[lane * PKS_COLS + col];
    return d && d.hp > 0 ? d : null;
  }

  function pksTargetAhead(lane, x) {
    var list = pksLane(lane);
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (e.hp > 0 && !e.cloaked && e.x > x && e.x <= PKS_FLOOR_END && e.x <= x + pksSight && pksInLane(e, lane)) return true;
    }
    return false;
  }

  function pksLaneOpen(sim, lane) {
    return lane >= 0 && lane < PKS_LANES && sim.breakers[lane] !== 'off';
  }

  function pksEmit(sim, event) {
    sim.events.push(event);
  }

  function pksShoot(sim, kind, lane, x, dir, dmg, owner, slow) {
    var s = { id: sim.nextId++, kind: kind, lane: lane, x: x, from: x, dir: dir, dmg: dmg, slow: slow, owner: owner.id, done: false };
    sim.shots.push(s);
    pksEmit(sim, { type: 'shot', id: s.id, kind: kind, owner: owner.id, lane: lane, x: x });
  }

  function pksDropDefender(sim, d, why) {
    d.hp = 0;
    pksEmit(sim, { type: 'destroyed', id: d.id, def: d.type, lane: d.lane, col: d.col, why: why });
    if (why !== 'spent') pksRestore(sim, d);
  }

  function pksNewSim(level, loadout) {
    var lv = typeof level === 'number' ? pksLevel(level) : level;
    var sim = {
      level: lv, n: lv.n, tick: 0, time: 0, rng: (lv.n * 7919 + 17) | 0, status: 'playing',
      cycles: lv.startCycles, trickleT: pksSteps(PKS_TRICKLE_EVERY),
      cards: [], defenders: [], enemies: [], shots: [], shells: [],
      breakers: [], tripped: 0, spawnIndex: 0, warned: 0, surged: 0,
      nextId: 1, stars: 0, events: [],
      stats: { kills: 0, placed: 0, spent: 0, produced: 0 },
      shimmers: [], blackout: null, outage: null, upkeep: null
    };
    pksZoneState(sim);
    var i;
    for (i = 0; i < PKS_LANES; i++) sim.breakers.push(lv.lanes.indexOf(i) === -1 ? 'off' : 'armed');
    for (i = 0; i < loadout.length; i++) {
      var def = PKS_DEF[loadout[i]];
      if (!def || pksCard(sim, def.id)) continue;
      sim.cards.push({ id: def.id, cost: def.cost, recharge: pksSteps(def.recharge), left: 0 });
    }
    return sim;
  }

  function pksCard(sim, id) {
    for (var i = 0; i < sim.cards.length; i++) {
      if (sim.cards[i].id === id) return sim.cards[i];
    }
    return null;
  }

  function pksOccupant(sim, lane, col) {
    for (var i = 0; i < sim.defenders.length; i++) {
      var d = sim.defenders[i];
      if (d.lane === lane && d.col === col && d.hp > 0) return d;
    }
    return null;
  }

  function pksIsBlocked(level, lane, col) {
    for (var i = 0; i < level.blocked.length; i++) {
      if (level.blocked[i].lane === lane && level.blocked[i].col === col) return true;
    }
    return false;
  }

  function pksOnField(lane, col) {
    return lane >= 0 && lane < PKS_LANES && col >= 0 && col < PKS_COLS && lane === Math.floor(lane) && col === Math.floor(col);
  }

  function pksCanPlace(sim, cardId, lane, col) {
    var r = { ok: false, reason: null, card: cardId, lane: lane, col: col };
    var card = pksCard(sim, cardId);
    var occupant;
    if (sim.status !== 'playing') {
      r.reason = 'over';
    } else if (!card) {
      r.reason = 'no-card';
    } else if (card.left > 0) {
      r.reason = 'recharging';
      r.seconds = Math.ceil(card.left / (PKS_RATE / 10)) / 10;
      r.recharge = card.recharge / PKS_RATE;
    } else if (sim.cycles < card.cost) {
      r.reason = 'cycles';
      r.have = sim.cycles;
      r.need = card.cost;
    } else if (!pksOnField(lane, col)) {
      r.reason = 'off-field';
    } else if (!pksLaneOpen(sim, lane)) {
      r.reason = 'lane-closed';
      r.lanes = sim.level.lanes.slice();
    } else if (pksIsBlocked(sim.level, lane, col)) {
      r.reason = 'blocked';
    } else if (pksTunnelAt(sim.level, lane, col)) {
      r.reason = 'tunnel';
    } else if ((occupant = pksOccupant(sim, lane, col)) !== null) {
      r.reason = 'occupied';
      r.occupant = occupant.type;
      r.occupantId = occupant.id;
    } else {
      r.ok = true;
    }
    if (card) {
      r.cost = card.cost;
      r.cycles = sim.cycles;
    }
    return r;
  }

  function pksPlace(sim, cardId, lane, col) {
    var r = pksCanPlace(sim, cardId, lane, col);
    if (!r.ok) return r;
    var card = pksCard(sim, cardId);
    var d = pksNewDefender(sim, cardId, lane, col);
    sim.defenders.push(d);
    sim.cycles -= card.cost;
    card.left = card.recharge;
    sim.stats.placed++;
    sim.stats.spent += card.cost;
    r.id = d.id;
    pksEmit(sim, { type: 'placed', id: d.id, def: cardId, lane: lane, col: col, cost: card.cost });
    return r;
  }

  function pksRemove(sim, lane, col) {
    var r = { ok: false, reason: null, lane: lane, col: col };
    var d = pksOccupant(sim, lane, col);
    if (sim.status !== 'playing') {
      r.reason = 'over';
    } else if (!d) {
      r.reason = 'empty';
    } else {
      sim.defenders.splice(sim.defenders.indexOf(d), 1);
      r.ok = true;
      r.id = d.id;
      r.def = d.type;
      pksEmit(sim, { type: 'removed', id: d.id, def: d.type, lane: lane, col: col });
    }
    return r;
  }

  function pksStars(sim) {
    if (sim.status !== 'won') return 0;
    if (sim.tripped === 0) return 3;
    return sim.tripped <= 2 ? 2 : 1;
  }

  function pksStep(sim) {
    sim.events = [];
    if (sim.status !== 'playing') return sim;
    sim.tick++;
    sim.time = sim.tick / PKS_RATE;
    pksLateStep = sim.n > PKS_FROZEN_LEVELS;
    pksEconomy(sim);
    pksSpawns(sim);
    pksZoneStep(sim);
    pksIndexField(sim);
    pksAuras(sim);
    var i;
    for (i = 0; i < sim.defenders.length; i++) {
      if (sim.defenders[i].hp > 0) pksDefenderAct(sim, sim.defenders[i]);
    }
    for (i = 0; i < sim.shots.length; i++) pksShotAct(sim, sim.shots[i]);
    for (i = 0; i < sim.shells.length; i++) pksShellAct(sim, sim.shells[i]);
    for (i = 0; i < sim.enemies.length && sim.status === 'playing'; i++) {
      if (sim.enemies[i].hp > 0) pksEnemyAct(sim, sim.enemies[i]);
    }
    pksCrossings(sim);
    pksBlasts(sim);
    pksSweep(sim);
    if (sim.status === 'playing') pksOvertime(sim);
    if (sim.status === 'playing' && sim.spawnIndex >= sim.level.spawns.length && sim.enemies.length === 0 && sim.shimmers.length === 0) {
      sim.status = 'won';
      sim.stars = pksStars(sim);
      pksEmit(sim, { type: 'win', stars: sim.stars });
      if (sim.level.unlock) pksEmit(sim, { type: 'unlock', def: sim.level.unlock });
    }
    return sim;
  }

  function pksEconomy(sim) {
    if (sim.level.trickle && --sim.trickleT === 0) {
      var amount = sim.level.rules ? sim.level.rules.trickle : PKS_TRICKLE;
      sim.trickleT = pksSteps(PKS_TRICKLE_EVERY);
      sim.cycles += amount;
      pksEmit(sim, { type: 'trickle', amount: amount });
    }
    for (var i = 0; i < sim.cards.length; i++) {
      if (sim.cards[i].left > 0) sim.cards[i].left--;
    }
  }

  function pksSpawns(sim) {
    var lv = sim.level;
    pksEmerge(sim);
    while (sim.spawnIndex < lv.spawns.length && pksSteps(lv.spawns[sim.spawnIndex].t) <= sim.tick) {
      var s = lv.spawns[sim.spawnIndex++];
      if (s.tunnel) pksShimmer(sim, s);
      else pksSpawnEnemy(sim, s.type, s.lane, PKS_SPAWN_X, s.type === 'boss' ? lv.boss : 0);
    }
    if (sim.warned < lv.surges.length && pksSteps(lv.surges[sim.warned] - PKS_SURGE_WARN) <= sim.tick) {
      pksEmit(sim, { type: 'surgeWarn', index: sim.warned, at: lv.surges[sim.warned] });
      sim.warned++;
    }
    if (sim.surged < lv.surges.length && pksSteps(lv.surges[sim.surged]) <= sim.tick) {
      pksEmit(sim, { type: 'surge', index: sim.surged });
      sim.surged++;
    }
  }

  function pksShotAct(sim, s) {
    s.x += s.dir * PKS_SHOT_SPEED / PKS_RATE;
    if (s.dir > 0 && (s.kind === 'phish' || s.kind === 'volley')) {
      pksReturnAct(sim, s);
      return;
    }
    if (s.dir > 0) {
      var list = pksLane(s.lane);
      var hit = null;
      for (var i = 0; i < list.length; i++) {
        var e = list[i];
        if (e.hp > 0 && !e.cloaked && e.x >= s.from && e.x - PKS_BODY <= s.x && (!hit || e.x < hit.x) && pksInLane(e, s.lane)) hit = e;
      }
      if (hit) {
        s.done = true;
        pksEmit(sim, { type: 'hit', id: hit.id, shot: s.id, kind: s.kind, lane: s.lane, x: hit.x, dmg: s.dmg });
        if (s.kind === 'decrypt') {
          pksDecryptHit(sim, hit, s.dmg);
          return;
        }
        if (s.slow > 0 && hit.shield <= 0) pksSlow(hit, s.slow);
        pksHurt(sim, hit, s.dmg, 'shot');
      } else if (s.x > PKS_SHOT_END) {
        s.done = true;
      }
      return;
    }
    var col = Math.floor(s.x);
    var d = pksCell(s.lane, col);
    if (d && d.type === 'airgap' && s.x <= col + 0.5) {
      pksReflect(sim, s, d);
    } else if (d && d.kind !== 'floor' && s.x <= col + 0.5) {
      s.done = true;
      d.hp -= s.dmg;
      d.flash = PKS_FLASH;
      pksEmit(sim, { type: 'hit', id: d.id, shot: s.id, kind: s.kind, lane: s.lane, x: s.x, dmg: s.dmg });
      if (d.hp <= 0) pksDropDefender(sim, d, 'shot');
    } else if (s.x < 0) {
      s.done = true;
    }
  }

  function pksSweep(sim) {
    pksKeep(sim.enemies, 'hp');
    pksKeep(sim.defenders, 'hp');
    pksKeepLive(sim.shots);
    pksKeepLive(sim.shells);
  }

  function pksKeepLive(list) {
    var w = 0;
    for (var i = 0; i < list.length; i++) {
      if (!list[i].done) list[w++] = list[i];
    }
    list.length = w;
  }

  function pksKeep(list, field) {
    var w = 0;
    for (var i = 0; i < list.length; i++) {
      if (list[i][field] > 0) list[w++] = list[i];
    }
    list.length = w;
  }

  // ── src/enemies-late.js ──

  // ── enemies: the expansion, 2 of 2 parts: the rules of the twelve new enemies ──

  var PKS_SLIDE_TIME = 0.3;    // seconds a knockback, blink or throw slides
  var pksAmpScratch = [];      // the Amplifiers on the floor this step (not state)
  var pksJamScratch = [];      // the Jammers on the floor this step (not state)

  function pksNear(a, lane, x, r) {
    var dl = a.lane - lane;
    var dx = a.x - x;
    return dl * dl + dx * dx <= r * r;
  }

  function pksInAura(e, list) {
    for (var i = 0; i < list.length; i++) {
      if (list[i] !== e && pksNear(list[i], e.lane, e.x, list[i].aura)) return true;
    }
    return false;
  }

  function pksAuras(sim) {
    var i;
    pksAmpScratch.length = 0;
    pksJamScratch.length = 0;
    for (i = 0; i < sim.enemies.length; i++) {
      var e = sim.enemies[i];
      var r = e.tier > 0 ? PKS_BOSS_TIERS[e.tier - 1].jam : PKS_ENEMY[e.type].aura;
      e.aura = r && e.frozen === 0 && e.x <= PKS_FLOOR_END ? r : 0;
      if (e.aura > 0 && e.type === 'amplifier') pksAmpScratch.push(e);
      if (e.aura > 0 && (e.type === 'jammer' || e.tier > 0)) pksJamScratch.push(e);
    }
    for (i = 0; i < sim.enemies.length; i++) sim.enemies[i].amped = pksAmpScratch.length > 0 && pksInAura(sim.enemies[i], pksAmpScratch);
    var dbs = false;
    for (i = 0; i < sim.defenders.length; i++) {
      if (sim.defenders[i].type === 'sigdb') dbs = true;
    }
    for (i = 0; i < sim.defenders.length; i++) {
      var d = sim.defenders[i];
      var shooter = PKS_SHOOTER_KIND[d.kind] === true;
      var jam = shooter && pksJamScratch.length > 0 && pksJammedAt(d);
      if (jam !== d.jammed) {
        d.jammed = jam;
        pksEmit(sim, { type: 'jam', id: d.id, lane: d.lane, col: d.col, on: jam });
      }
      d.boosted = shooter && dbs && pksBoostedNow(sim, d);
    }
  }

  function pksJammedAt(d) {
    for (var i = 0; i < pksJamScratch.length; i++) {
      if (pksNear(pksJamScratch[i], d.lane, d.col + 0.5, pksJamScratch[i].aura)) return true;
    }
    return false;
  }

  function pksLateEnemyAct(sim, e) {
    switch (e.type) {
      case 'hive':
        pksHiveAct(sim, e);
        break;
      case 'hydra':
        pksHydraAct(sim, e);
        break;
      case 'dropper':
        pksDropperAct(sim, e);
        break;
      case 'glitch':
        pksGlitchAct(sim, e);
        break;
    }
  }

  function pksDue(e) {
    if (e.x > PKS_FLOOR_END) return false;
    if (e.t > 0) e.t--;
    return e.t === 0;
  }

  function pksHiveAct(sim, e) {
    var def = PKS_ENEMY.hive;
    if (!pksDue(e)) return;
    e.t = pksSteps(def.every);
    var own = 0;
    for (var i = 0; i < sim.enemies.length; i++) {
      if (sim.enemies[i].hive === e.id && sim.enemies[i].hp > 0) own++;
    }
    if (own >= def.cap) return;
    var c = pksSpawnEnemy(sim, def.release, e.lane, e.x, 0);
    c.hive = e.id;
    pksEmit(sim, { type: 'release', id: e.id, lane: e.lane, x: e.x, child: c.id });
  }

  function pksHydraAct(sim, e) {
    if (e.x > PKS_FLOOR_END) return;
    var def = PKS_ENEMY.hydra;
    for (var l = e.lane - 1; l <= e.lane + 1; l++) {
      var list = pksLane(l);
      for (var i = 0; i < list.length; i++) {
        var o = list[i];
        if (o === e || o.hp <= 0 || o.hp >= o.maxHp || o.mended === sim.tick || pksHeavy(o) || !pksNear(e, o.lane, o.x, def.aura)) continue;
        o.mended = sim.tick;
        o.hp = Math.min(o.maxHp, o.hp + def.heal / PKS_RATE);
      }
    }
  }

  function pksDropperAct(sim, e) {
    var def = PKS_ENEMY.dropper;
    if (!pksDue(e)) return;
    e.t = pksSteps(def.every);
    var at = pksBlocker(e);
    if (at && at.kind === 'decoy') return;
    var to = e.x - def.ahead;
    for (var col = 0; col < PKS_COLS; col++) {
      var g = pksCell(e.lane, col);
      if (g && g.type === 'airgap' && col + 0.5 > to && col + 0.5 < e.x) to = col + 0.5 + PKS_REACH;
    }
    to = Math.max(to, def.minX);
    if (to > e.x - 0.5) return;
    var b = pksSpawnEnemy(sim, def.drop, e.lane, to, 0);
    b.moveFrom = e.x;
    b.move = pksSteps(PKS_SLIDE_TIME);
    pksEmit(sim, { type: 'throw', id: e.id, lane: e.lane, x: e.x, to: to, child: b.id });
  }

  function pksGlitchAct(sim, e) {
    var def = PKS_ENEMY.glitch;
    if (!pksDue(e)) return;
    e.t = pksSteps(def.every);
    if (pksInside(e)) return;
    var to = e.x - def.blink;
    for (var col = 0; col < PKS_COLS; col++) {
      var d = pksCell(e.lane, col);
      if (d && d.kind !== 'floor' && col + 0.5 < e.x) to = Math.max(to, col + 0.5 + PKS_REACH);
    }
    if (to >= e.x) return;
    pksEmit(sim, { type: 'blink', id: e.id, lane: e.lane, x: e.x, to: to });
    e.moveFrom = e.x;
    e.x = to;
    e.move = pksSteps(PKS_SLIDE_TIME);
  }

  function pksSteal(sim, e) {
    if (e.t > 0) e.t--;
    if (e.t > 0) return;
    e.t = pksSteps(1 / PKS_ENEMY.keylogger.steal);
    if (sim.cycles <= 0) return;
    sim.cycles--;
    pksEmit(sim, { type: 'steal', id: e.id, lane: e.lane, x: e.x, amount: 1 });
  }

  function pksWipe(sim, e, d) {
    pksEmit(sim, { type: 'wipe', id: d.id, def: d.type, by: e.id, lane: d.lane, col: d.col });
    pksDropDefender(sim, d, 'wiped');
    pksKill(sim, e, 'wipe');
  }

  function pksStopsLeap(d) {
    return d.type === 'proxy' || d.type === 'airgap' || d.kind === 'decoy';
  }

  function pksShieldTake(sim, e, dmg) {
    e.flash = PKS_FLASH;
    if (dmg < e.shield) {
      e.shield -= dmg;
      return 0;
    }
    dmg -= e.shield;
    e.shield = 0;
    pksEmit(sim, { type: 'shieldBreak', id: e.id, lane: e.lane, x: e.x, by: 'shot' });
    return dmg;
  }

  function pksSplit(sim, e) {
    e.hp = 0;
    var a = pksCopy(sim, e, e.x);
    var b = pksCopy(sim, e, Math.min(PKS_SPAWN_X, e.x + 0.4));
    pksEmit(sim, { type: 'split', id: e.id, lane: e.lane, x: e.x, gen: e.gen + 1, children: [a.id, b.id] });
  }

  function pksCopy(sim, e, x) {
    var c = pksSpawnEnemy(sim, 'replicator', e.lane, x, 0);
    c.gen = e.gen + 1;
    c.maxHp = e.maxHp / 2;
    c.hp = c.maxHp;
    c.slow = e.slow;
    c.frozen = e.frozen;
    return c;
  }

  function pksHeavy(e) {
    return e.tier > 0 || e.type === 'titan';
  }

  function pksBlasts(sim) {
    for (var i = 0; i < sim.enemies.length; i++) {
      var e = sim.enemies[i];
      if (e.type === 'logicbomb' && e.used) {
        e.used = false;
        pksDetonate(sim, e);
      }
    }
  }

  function pksDetonate(sim, e) {
    if (e.x > PKS_FLOOR_END) return;
    var dmg = PKS_ENEMY.logicbomb.blast;
    var col = Math.max(0, Math.min(PKS_COLS - 1, Math.floor(e.x)));
    pksEmit(sim, { type: 'detonate', id: e.id, lane: e.lane, x: e.x, col: col, dmg: dmg });
    for (var l = e.lane - 1; l <= e.lane + 1; l++) {
      for (var c = col - 1; c <= col + 1; c++) {
        var d = pksCell(l, c);
        if (!d) continue;
        d.hp -= dmg;
        d.flash = PKS_FLASH;
        if (d.hp <= 0) pksDropDefender(sim, d, 'blast');
      }
    }
  }

  // ── src/defenders-late.js ──

  // ── defenders: the expansion, 2 of 2 parts: the rules of the twelve new defenders ──

  var PKS_SHOOTER_KINDS = ['shooter', 'beam', 'sniper', 'mortar', 'arc', 'decrypt'];
  var PKS_SHOOTER_KIND = pksKindSet(PKS_SHOOTER_KINDS);   // the same as a lookup

  function pksKindSet(kinds) {
    var set = {};
    for (var i = 0; i < kinds.length; i++) set[kinds[i]] = true;
    return set;
  }

  function pksBoosted(d, dmg) {
    return d.boosted ? dmg * (1 + PKS_DEF.sigdb.boost / 100) : dmg;
  }

  function pksBoostedNow(sim, d) {
    for (var l = d.lane - 1; l <= d.lane + 1; l++) {
      for (var c = d.col - 1; c <= d.col + 1; c++) {
        var o = pksCell(l, c);
        if (o && o.type === 'sigdb' && o.off === 0 && o.lane !== pksDownLane) return true;
      }
    }
    return false;
  }

  function pksLateDefenderAct(sim, d, def) {
    if (d.t > 0) return;
    switch (d.kind) {
      case 'sniper':
        if (!d.jammed) pksTrace(sim, d, def);
        break;
      case 'mortar':
        if (!d.jammed) pksLob(sim, d, def);
        break;
      case 'arc':
        if (!d.jammed) pksArc(sim, d, def);
        break;
      case 'decrypt':
        if (!d.jammed && pksTargetAhead(d.lane, d.col + 0.5)) {
          pksShoot(sim, 'decrypt', d.lane, d.col + 0.7, 1, pksBoosted(d, def.dmg), d, 0);
          pksFired(d, def);
        }
        break;
      case 'knock':
        pksKnock(sim, d, def);
        break;
      case 'pull':
        pksPull(sim, d, def);
        break;
    }
  }

  function pksFired(d, def) {
    d.t = pksSteps(def.every);
    d.fire = PKS_FIRE_ANIM;
  }

  function pksSeen(e, d) {
    return e.hp > 0 && !e.cloaked && e.x > d.col + 0.5 && e.x <= PKS_FLOOR_END && e.x <= d.col + 0.5 + pksSight && pksInLane(e, d.lane);
  }

  function pksFirstAhead(d, fresh) {
    var list = pksLane(d.lane);
    var best = null;
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (pksSeen(e, d) && !(fresh && (e.knocked > 0 || e.knocks >= PKS_DEF.loopback.times)) && (!best || e.x < best.x)) best = e;
    }
    return best;
  }

  function pksTrace(sim, d, def) {
    var list = pksLane(d.lane);
    var best = null;
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (!pksSeen(e, d)) continue;
      var tough = e.hp + e.shield;
      if (!best || tough > best.hp + best.shield || (tough === best.hp + best.shield && e.x < best.x)) best = e;
    }
    if (!best) return;
    var dmg = pksBoosted(d, def.dmg);
    pksEmit(sim, { type: 'trace', id: d.id, def: d.type, lane: d.lane, col: d.col, target: best.id, x: best.x, dmg: dmg });
    pksFired(d, def);
    pksHurt(sim, best, dmg, 'shot');
  }

  function pksCrowd(list, lane, x, r) {
    var n = 0;
    for (var i = 0; i < list.length; i++) {
      if (list[i].hp > 0 && list[i].x <= PKS_FLOOR_END && Math.abs(list[i].x - x) <= r && pksInLane(list[i], lane)) n++;
    }
    return n;
  }

  function pksLob(sim, d, def) {
    var list = pksLane(d.lane);
    var best = null;
    var most = 0;
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (!pksSeen(e, d) || e.x - (d.col + 0.5) < def.minRange) continue;
      var n = pksCrowd(list, d.lane, e.x, def.splash);
      if (n > most || (n === most && e.x < best.x)) {
        best = e;
        most = n;
      }
    }
    if (!best) return;
    var flight = pksSteps(def.flight);
    var s = {
      id: sim.nextId++, owner: d.id, lane: d.lane, from: d.col + 0.5, to: best.x, t: flight, flight: flight,
      dmg: pksBoosted(d, def.dmg), splash: def.splash, done: false
    };
    sim.shells.push(s);
    pksEmit(sim, { type: 'lob', id: d.id, def: d.type, lane: d.lane, col: d.col, shell: s.id, to: s.to, flight: flight });
    pksFired(d, def);
  }

  function pksShellAct(sim, s) {
    if (--s.t > 0) return;
    s.done = true;
    pksEmit(sim, { type: 'splash', id: s.id, owner: s.owner, lane: s.lane, x: s.to, radius: s.splash });
    var list = pksLane(s.lane);
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (e.hp > 0 && e.x <= PKS_FLOOR_END && Math.abs(e.x - s.to) <= s.splash && pksInLane(e, s.lane)) pksHurt(sim, e, s.dmg, 'area');
    }
  }

  function pksKnock(sim, d, def) {
    var e = pksFirstAhead(d, true);
    if (!e) return;
    var from = e.x;
    e.x = Math.min(PKS_FLOOR_END, e.x + (pksHeavy(e) ? def.heavyPush : def.push));
    var col = Math.ceil(e.x) - 1;
    var back = pksCell(e.lane, col);
    if (back && back.kind !== 'floor' && e.x <= col + 0.5) e.x = col;
    if (e.state === 'leaping') e.state = 'walking';
    e.moveFrom = from;
    e.move = pksSteps(PKS_SLIDE_TIME);
    e.knocked = pksSteps(def.every);
    e.knocks++;
    pksEmit(sim, { type: 'knock', id: d.id, def: d.type, target: e.id, lane: e.lane, from: from, to: e.x });
    pksFired(d, def);
  }

  function pksArc(sim, d, def) {
    var first = pksFirstAhead(d, false);
    if (!first) return;
    var path = [first];
    var last = first;
    while (path.length < def.hits) {
      var next = null;
      var best = 0;
      for (var l = last.lane - 1; l <= last.lane + 1; l++) {
        var list = pksLane(l);
        for (var i = 0; i < list.length; i++) {
          var o = list[i];
          if (o.hp <= 0 || o.x > PKS_FLOOR_END || path.indexOf(o) >= 0) continue;
          var dl = o.lane - last.lane;
          var dx = o.x - last.x;
          var dist = dl * dl + dx * dx;
          if (dist <= def.reach * def.reach && (!next || dist < best)) {
            next = o;
            best = dist;
          }
        }
      }
      if (!next) break;
      path.push(next);
      last = next;
    }
    var dmg = pksBoosted(d, def.dmg);
    var out = [];
    for (var j = 0; j < path.length; j++) out.push({ id: path[j].id, lane: path[j].lane, x: path[j].x });
    pksEmit(sim, { type: 'arc', id: d.id, def: d.type, lane: d.lane, col: d.col, dmg: dmg, path: out });
    pksFired(d, def);
    for (j = 0; j < path.length; j++) pksHurt(sim, path[j], dmg, 'area');
  }

  function pksPull(sim, d, def) {
    var c = d.col + 0.5;
    var pulled = 0;
    for (var l = d.lane - 1; l <= d.lane + 1; l += 2) {
      var list = pksLane(l);
      var best = null;
      for (var i = 0; i < list.length; i++) {
        var e = list[i];
        if (e.hp <= 0 || e.cloaked || e.lane !== l || e.x > PKS_FLOOR_END || pksHeavy(e) || e.state === 'leaping') continue;
        if (!best || Math.abs(e.x - c) < Math.abs(best.x - c)) best = e;
      }
      if (!best) continue;
      pksEmit(sim, { type: 'pull', id: d.id, def: d.type, target: best.id, from: l, lane: d.lane, x: best.x });
      pksShift(best, d.lane);
      pulled++;
    }
    if (pulled > 0) pksFired(d, def);
  }

  function pksReflect(sim, s, d) {
    s.dir = 1;
    s.from = s.x;
    d.flash = PKS_FLASH;
    pksEmit(sim, { type: 'reflect', id: s.id, by: d.id, lane: s.lane, x: s.x, owner: s.owner });
  }

  function pksReturnAct(sim, s) {
    var list = pksLane(s.lane);
    for (var i = 0; i < list.length; i++) {
      var e = list[i];
      if (e.id === s.owner && e.hp > 0 && e.x - PKS_BODY <= s.x && pksInLane(e, s.lane)) {
        s.done = true;
        pksEmit(sim, { type: 'hit', id: e.id, shot: s.id, kind: s.kind, lane: s.lane, x: e.x, dmg: s.dmg });
        pksHurt(sim, e, s.dmg, 'shot');
        return;
      }
    }
    if (s.x > PKS_SHOT_END) s.done = true;
  }

  function pksDecryptHit(sim, e, dmg) {
    if (e.shield > 0) {
      e.shield = 0;
      pksEmit(sim, { type: 'shieldBreak', id: e.id, lane: e.lane, x: e.x, by: 'decrypt' });
      dmg *= 2;
    } else if (PKS_DEF.decryptor.armoured.indexOf(e.type) >= 0) {
      dmg *= 2;
    }
    pksHurt(sim, e, dmg, 'shot');
  }

  function pksScrub(sim, d, def) {
    pksEmit(sim, { type: 'scrub', id: d.id, def: d.type, lane: d.lane, col: d.col });
    for (var i = 0; i < sim.enemies.length; i++) {
      var e = sim.enemies[i];
      if (e.hp > 0 && e.maxHp <= def.limit && e.x <= PKS_FLOOR_END) pksKill(sim, e, 'instant');
    }
  }

  function pksRestore(sim, d) {
    if (d.kind === 'instant' || d.kind === 'decoy' || d.type === 'backup') return;
    for (var i = 0; i < sim.defenders.length; i++) {
      var b = sim.defenders[i];
      if (b.type !== 'backup' || b.hp <= 0 || b.off > 0 || b.t > 0 || b.lane === pksDownLane || Math.abs(b.lane - d.lane) > 1 || Math.abs(b.col - d.col) > 1) continue;
      var n = pksNewDefender(sim, d.type, d.lane, d.col);
      sim.defenders.push(n);
      pksCellScratch[d.lane * PKS_COLS + d.col] = n;
      b.t = pksSteps(PKS_DEF.backup.every);
      b.fire = PKS_FIRE_ANIM;
      pksEmit(sim, { type: 'restore', id: n.id, by: b.id, old: d.id, def: d.type, lane: d.lane, col: d.col });
      return;
    }
  }

  // ── src/zones.js ──

  // ── zones: the rules of zones 6-15 as they play in the sim ──

  var PKS_EXPRESS = 1.4;       // speed factor of an express lane
  var PKS_HOT_DPS = 8;         // HP/s a hot cell takes from its defender
  var PKS_RAIL = 1.5;          // work rate on a power rail
  var PKS_TUNNEL_COL = 6;      // the column of a tunnel exit
  var PKS_TUNNEL_EVERY = 3;    // every this many spawns of a tunnel lane come out of it
  var PKS_SHIMMER = 2;         // seconds a tunnel shimmers before the enemy appears
  var PKS_BLACKOUT = { every: 50, length: 10, warn: 3, sight: 4 };
  var PKS_UPKEEP = { cost: 1, every: 12 };
  var PKS_OUTAGE = { every: 40, length: 10, warn: 5 };
  var PKS_LATE_FOG = 5;        // fog columns in the quantum lab
  var PKS_ROOT_SPEED = 1.1;    // enemy speed factor at the root
  var PKS_OVERTIME = 300;      // s past a late level's nominal end before it is lost

  var pksLaneSpeed = [1, 1, 1, 1, 1];
  var pksSight = Infinity;
  var pksDownLane = -1;
  var pksRailCells = [];
  var pksHotCells = [];

  function pksNoRules() {
    return {
      names: [], express: [], hot: [], rails: [], tunnels: [], cross: [],
      blackout: null, upkeep: null, outage: null, trickle: PKS_TRICKLE
    };
  }

  var PKS_NO_RULES = pksNoRules();

  function pksRules(level) {
    return level.rules || PKS_NO_RULES;
  }

  function pksZoneState(sim) {
    var R = pksRules(sim.level);
    if (R.blackout) sim.blackout = { state: 'clear', t: pksSteps(R.blackout.every - R.blackout.warn), count: 0 };
    if (R.outage) sim.outage = { state: 'clear', lane: -1, next: R.outage.order[0], t: pksSteps(R.outage.every - R.outage.warn), count: 0 };
    if (R.upkeep) sim.upkeep = { t: pksSteps(R.upkeep.every), last: 0, due: 0 };
  }

  function pksZoneStep(sim) {
    var R = pksRules(sim.level);
    var i;
    for (i = 0; i < PKS_LANES; i++) pksLaneSpeed[i] = 1;
    for (i = 0; i < R.express.length; i++) pksLaneSpeed[R.express[i]] = PKS_EXPRESS;
    pksMarkCells(pksRailCells, R.rails);
    pksMarkCells(pksHotCells, R.hot);
    pksSight = Infinity;
    pksDownLane = -1;
    if (sim.blackout) pksBlackoutStep(sim, R.blackout);
    if (sim.outage) pksOutageStep(sim, R.outage);
    if (sim.upkeep) pksUpkeepStep(sim, R.upkeep);
    if (R.hot.length) pksHeat(sim);
  }

  function pksMarkCells(flags, cells) {
    var i;
    for (i = 0; i < PKS_LANES * PKS_COLS; i++) flags[i] = false;
    for (i = 0; i < cells.length; i++) flags[cells[i].lane * PKS_COLS + cells[i].col] = true;
  }

  function pksRailAt(d) {
    return pksRailCells[d.lane * PKS_COLS + d.col] === true;
  }

  function pksRailRate(d) {
    return pksRailAt(d) ? PKS_RAIL : 1;
  }

  function pksBlackoutStep(sim, rule) {
    var b = sim.blackout;
    if (--b.t <= 0) {
      if (b.state === 'clear') {
        b.state = 'warn';
        b.t = pksSteps(rule.warn);
        pksEmit(sim, { type: 'blackoutWarn', at: pksTenth(sim.time + rule.warn), length: rule.length });
      } else if (b.state === 'warn') {
        b.state = 'dark';
        b.t = pksSteps(rule.length);
        b.count++;
        pksEmit(sim, { type: 'blackout', on: true });
      } else {
        b.state = 'clear';
        b.t = pksSteps(rule.every - rule.warn - rule.length);
        pksEmit(sim, { type: 'blackout', on: false });
      }
    }
    if (b.state === 'dark') pksSight = rule.sight;
  }

  function pksOutageStep(sim, rule) {
    var o = sim.outage;
    if (--o.t <= 0) {
      if (o.state === 'clear') {
        o.state = 'warn';
        o.lane = o.next;
        o.t = pksSteps(rule.warn);
        pksEmit(sim, { type: 'outageWarn', lane: o.lane, at: pksTenth(sim.time + rule.warn), length: rule.length });
      } else if (o.state === 'warn') {
        o.state = 'down';
        o.t = pksSteps(rule.length);
        o.count++;
        pksEmit(sim, { type: 'outage', lane: o.lane, on: true });
      } else {
        pksEmit(sim, { type: 'outage', lane: o.lane, on: false });
        o.state = 'clear';
        o.lane = -1;
        o.next = rule.order[o.count % rule.order.length];
        o.t = pksSteps(rule.every - rule.warn - rule.length);
      }
    }
    if (o.state === 'down') pksDownLane = o.lane;
  }

  function pksUpkeepStep(sim, rule) {
    var u = sim.upkeep;
    if (--u.t > 0) return;
    u.t = pksSteps(rule.every);
    var due = 0;
    for (var i = 0; i < sim.defenders.length; i++) {
      if (sim.defenders[i].hp > 0 && sim.defenders[i].kind !== 'instant') due += rule.cost;
    }
    var take = Math.min(due, Math.max(0, sim.cycles));
    sim.cycles -= take;
    u.last = take;
    u.due = due;
    if (due > 0) pksEmit(sim, { type: 'upkeep', amount: take, due: due });
  }

  function pksHeat(sim) {
    var n = sim.defenders.length;
    for (var i = 0; i < n; i++) {
      var d = sim.defenders[i];
      if (d.hp <= 0 || !pksHotCells[d.lane * PKS_COLS + d.col]) continue;
      d.hp -= PKS_HOT_DPS / PKS_RATE;
      if (d.hp <= 0) pksDropDefender(sim, d, 'burnt');
    }
  }

  function pksTunnelOf(level, lane) {
    var list = pksRules(level).tunnels;
    for (var i = 0; i < list.length; i++) {
      if (list[i].lane === lane) return list[i];
    }
    return null;
  }

  function pksTunnelAt(level, lane, col) {
    var t = pksTunnelOf(level, lane);
    return t !== null && t.col === col;
  }

  function pksShimmer(sim, s) {
    var t = pksTunnelOf(sim.level, s.lane);
    var col = t ? t.col : PKS_TUNNEL_COL;
    var sh = { id: sim.nextId++, lane: s.lane, col: col, enemy: s.type, t: pksSteps(PKS_SHIMMER) };
    sim.shimmers.push(sh);
    pksEmit(sim, { type: 'shimmer', id: sh.id, lane: sh.lane, col: col, enemy: s.type, at: pksTenth(sim.time + PKS_SHIMMER) });
  }

  function pksEmerge(sim) {
    var list = sim.shimmers;
    var w = 0;
    for (var i = 0; i < list.length; i++) {
      var sh = list[i];
      if (--sh.t > 0) {
        list[w++] = sh;
        continue;
      }
      var e = pksSpawnEnemy(sim, sh.enemy, sh.lane, sh.col + 0.5, 0);
      pksEmit(sim, { type: 'emerge', id: e.id, shimmer: sh.id, enemy: sh.enemy, lane: sh.lane, col: sh.col, x: e.x });
    }
    list.length = w;
  }

  function pksOvertime(sim) {
    var lv = sim.level;
    if (!lv.rules || sim.spawnIndex < lv.spawns.length || sim.time < lv.duration + PKS_OVERTIME || !sim.enemies.length) return;
    var e = sim.enemies[0];
    for (var i = 1; i < sim.enemies.length; i++) {
      if (sim.enemies[i].x < e.x) e = sim.enemies[i];
    }
    sim.status = 'lost';
    pksEmit(sim, { type: 'overtime', at: pksTenth(sim.time) });
    pksEmit(sim, { type: 'lose', lane: e.lane, id: e.id, enemy: e.type });
  }

  function pksCrossings(sim) {
    var cross = pksRules(sim.level).cross;
    if (!cross.length) return;
    for (var i = 0; i < sim.enemies.length; i++) {
      var e = sim.enemies[i];
      if (e.hp <= 0 || e.frozen > 0 || e.state === 'leaping' || pksHeavy(e)) continue;
      for (var j = 0; j < cross.length; j++) {
        var c = cross[j];
        var key = c.lane * PKS_COLS + c.col;
        if (c.lane !== e.lane || e.x > c.col + 0.5 || e.x <= c.col - 0.5 || e.crossed.indexOf(key) >= 0 || !pksLaneOpen(sim, c.to)) continue;
        e.crossed.push(key);
        pksEmit(sim, { type: 'cross', id: e.id, from: e.lane, lane: c.to, col: c.col, x: e.x });
        pksShift(e, c.to);
        break;
      }
    }
  }

  // ── src/bosses.js ──

  // ── bosses: the abilities of boss tiers 6-15 ──

  function pksLateBossAct(sim, e, tier) {
    if (tier.shieldEvery > 0 && !e.used) pksShieldPhase(sim, e, tier);
    if (tier.mend > 0 && e.x <= PKS_FLOOR_END) pksMend(sim, e, tier);
  }

  function pksShieldPhase(sim, e, tier) {
    if (e.t <= 0) {
      e.t = pksSteps(tier.shieldEvery);
      return;
    }
    if (--e.t > 0) return;
    e.t = pksSteps(tier.shieldEvery);
    if (e.shield >= e.maxShield) return;
    e.shield = e.maxShield;
    pksEmit(sim, { type: 'shieldUp', id: e.id, lane: e.lane, x: e.x, shield: e.shield });
  }

  function pksMend(sim, e, tier) {
    var reach = Math.ceil(tier.mendReach);
    for (var l = e.lane - reach; l <= e.lane + reach; l++) {
      var list = pksLane(l);
      for (var i = 0; i < list.length; i++) {
        var o = list[i];
        if (o === e || o.hp <= 0 || o.hp >= o.maxHp || o.mended === sim.tick || pksHeavy(o) || !pksNear(e, o.lane, o.x, tier.mendReach)) continue;
        o.mended = sim.tick;
        o.hp = Math.min(o.maxHp, o.hp + tier.mend / PKS_RATE);
      }
    }
  }

  function pksBossSplit(sim, e) {
    var tier = PKS_BOSS_TIERS[e.tier - 1];
    if (!tier.split || e.used) return;
    var a = pksSplitCopy(sim, e, e.lane, e.x, tier);
    var b = pksSplitCopy(sim, e, pksNeighbourLane(sim, e.lane), Math.min(PKS_SPAWN_X, e.x + 0.4), tier);
    pksEmit(sim, { type: 'bossSplit', id: e.id, lane: e.lane, x: e.x, children: [a.id, b.id] });
  }

  function pksSplitCopy(sim, e, lane, x, tier) {
    var c = pksSpawnEnemy(sim, 'boss', lane, x, e.tier);
    c.hp = c.maxHp = tier.split;
    c.shield = c.maxShield = 0;
    c.used = true;
    c.frozen = e.frozen;
    c.slow = e.slow;
    return c;
  }

