  // ── src/unpack-art.js ──

  // ── unpack-art: the decoder of the art parts as build.js packs them ──

  var PKS_PACK_DIGITS = '0123456789!#$%&()*+,-/:;=?@[]^_{|}~';
  var PKS_PACK_ENDS = 25;

  function pksUnpackNumber(r) {
    var v = 0;
    var k;
    while ((k = PKS_PACK_DIGITS.indexOf(r.s.charAt(r.i++))) >= PKS_PACK_ENDS) {
      v = v * (PKS_PACK_DIGITS.length - PKS_PACK_ENDS) + k - PKS_PACK_ENDS;
    }
    return v * PKS_PACK_ENDS + k;
  }

  function pksUnpackArt(part) {
    var art = {};
    var px = [];
    for (var s = 0; s < part.length; s++) {
      var f = part[s].split(' ');
      var w = Number(f[1]);
      var h = Number(f[2]);
      var r = { s: f[3], i: 0 };
      var start = px.length;
      while (r.i < r.s.length) {
        if (PKS_PACK_DIGITS.indexOf(r.s.charAt(r.i)) < 0) {
          px.push(r.s.charAt(r.i++));
        } else {
          var back = pksUnpackNumber(r) + 1;
          for (var n = pksUnpackNumber(r) + 2; n > 0; n--) px.push(px[px.length - back]);
        }
      }
      var rows = [];
      for (var y = 0; y < h; y++) rows.push(px.slice(start + y * w, start + y * w + w).join(''));
      art[f[0]] = { w: w, h: h, rows: rows };
    }
    return art;
  }

  // ── src/sprites.js ──

  // ── sprites: the palette, the sprite table and the atlas builder ──

  var PKS_PALETTE = {
    k: '#05080f',
    K: '#0d1424',
    a: '#141c2e',
    A: '#1f2a40',
    l: '#34466b',
    N: '#5b6b85',
    n: '#9aa8bd',
    w: '#eef3fa',
    c: '#22d3ee',
    C: '#0e7490',
    B: '#3b82f6',
    b: '#1e3a8a',
    G: '#4ade80',
    g: '#16a34a',
    d: '#0b5d3b',
    y: '#fbbf24',
    Y: '#b45309',
    o: '#f97316',
    r: '#ef4444',
    R: '#991b1b',
    P: '#a78bfa',
    p: '#6d28d9',
    m: '#f472b6',
    M: '#9d174d',
    h: '#10261f',
    H: '#1a3a2f',
    e: '#2a1a10',
    E: '#4a2c17',
    v: '#0c2532',
    V: '#17405a',
    u: '#1a1030',
    U: '#2d1b4e',
    s: '#a3e635',  // lime: Keylogger shell, Signature DB bands, power-rail glow
    S: '#3f6212',  // dark lime: lime shading, power-plant floor lines
    t: '#2dd4bf',  // aqua: Hydra, Loopback arrow, heal aura, crossover arrows
    x: '#e11d48',  // crimson: Tracer scope and shot, Logic Bomb timer, Air Gap stripes, Glitch split, root zone
    f: '#e879f9',  // fuchsia: Jammer, Sinkhole swirl, tunnel portal, Glitch split
    j: '#d6a36a',  // tan: Batch Job bands and shell, Amplifier trim, coil copper, Honeynet comb, splash
    q: '#818cf8',  // periwinkle: Encrypted Payload and its shield, Token Ring, Decryptor code
    Q: '#1b1946',  // deep indigo: Backbone floor (zone 6), Payload shading
    Z: '#28241f',  // graphite: Storage array floor (zone 7)
    I: '#1f2510',  // dark olive: Power plant floor (zone 8)
    F: '#2e0e33',  // plum: VPN tunnel floor (zone 9), fuchsia shading
    X: '#2b0a12',  // wine: Root floor (zone 15), outage stripes, hot cell base
    i: '#0c2c29',  // dark teal: Cross-connect floor (zone 11)
    T: '#2e3238',  // steel grey: Mainframe raised floor (zone 13)
    J: '#2d2846'   // dusk grey: Metered cloud floor (zone 12), Honeynet frame
  };

  var PKS_SPRITES = pksJoinArt([PKS_ART_SUPPORT, PKS_ART_SHOOTERS, PKS_ART_EARLY, PKS_ART_LATE, PKS_ART_FLOOR, PKS_ART_FX,
    PKS_ART_150_DEF, PKS_ART_150_ENM_A, PKS_ART_150_ENM_B, PKS_ART_150_BOSS, PKS_ART_150_FLOOR_A, PKS_ART_150_FLOOR_B,
    PKS_ART_150_FX]);
  var PKS_ATLAS_W = 1024;
  var PKS_UNIT_ART = /^(def|enm|boss\d?)-/;
  var PKS_BOSS_BODIES = ['boss-', 'boss2-', 'boss3-'];
  var PKS_BOSS_POSES = ['walk0', 'walk1', 'cast0', 'cast1'];
  var PKS_TINT_FLOOR = 0.45;    // colours at most this saturated keep their hue

  function pksBossBody(row) {
    return PKS_BOSS_BODIES[(row && row.body) - 1] || PKS_BOSS_BODIES[0];
  }

  function pksHueShift(hex, deg) {
    var rgb = [1, 3, 5].map(function (i) { return parseInt(hex.substr(i, 2), 16) / 255; });
    var max = Math.max(rgb[0], rgb[1], rgb[2]);
    var min = Math.min(rgb[0], rgb[1], rgb[2]);
    var l = (max + min) / 2;
    var d = max - min;
    var s = d / (1 - Math.abs(2 * l - 1));
    if (!(s > PKS_TINT_FLOOR)) return hex;
    var h = max === rgb[0] ? (rgb[1] - rgb[2]) / d + 6 : max === rgb[1] ? (rgb[2] - rgb[0]) / d + 2 : (rgb[0] - rgb[1]) / d + 4;
    h = (h * 60 + deg) % 360;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(h / 60 % 2 - 1));
    var k = [[c, x, 0], [x, c, 0], [0, c, x], [0, x, c], [x, 0, c], [c, 0, x]][Math.floor(h / 60)];
    var out = '#';
    for (var i = 0; i < 3; i++) out += ('0' + Math.round((k[i] + l - c / 2) * 255).toString(16)).slice(-2);
    return out;
  }

  function pksTintJobs(atlas, jobs) {
    var maps = {};
    var seen = {};
    var keys = Object.keys(PKS_PALETTE);
    for (var t = 0; t < PKS_BOSS_TIERS.length; t++) {
      var hue = PKS_BOSS_TIERS[t].hue;
      if (!hue) continue;
      if (!maps[hue]) {
        maps[hue] = {};
        atlas.tints[hue] = {};
        for (var k = 0; k < keys.length; k++) maps[hue][keys[k]] = pksHueShift(PKS_PALETTE[keys[k]], hue);
      }
      var prefix = pksBossBody(PKS_BOSS_TIERS[t]);
      for (var p = 0; p < PKS_BOSS_POSES.length; p++) {
        var name = prefix + PKS_BOSS_POSES[p];
        seen[hue + name] = seen[hue + name] || jobs[jobs.push({ into: atlas.tints[hue], map: maps[hue], name: name }) - 1];
      }
    }
  }

  function pksJoinArt(parts) {
    var all = {};
    for (var i = 0; i < parts.length; i++) {
      var art = pksUnpackArt(parts[i]);
      var names = Object.keys(art);
      for (var j = 0; j < names.length; j++) all[names[j]] = art[names[j]];
    }
    return all;
  }

  function pksBuildAtlas(makeCanvas) {
    var WIDTH = PKS_ATLAS_W;
    var names = Object.keys(PKS_SPRITES);
    var keys = Object.keys(PKS_PALETTE);
    var flash = {};
    var slow = {};
    var atlas = { canvas: null, frames: {}, flash: {}, slow: {}, tints: {} };
    var jobs = [];
    var i, j, c;
    for (i = 0; i < keys.length; i++) {
      var hex = PKS_PALETTE[keys[i]];
      var lum = parseInt(hex.substr(1, 2), 16) * 0.3 + parseInt(hex.substr(3, 2), 16) * 0.59 +
        parseInt(hex.substr(5, 2), 16) * 0.11;
      flash[keys[i]] = '#ffffff';
      slow[keys[i]] = 'rgb(' + Math.round(20 + lum * 0.45) + ',' + Math.round(50 + lum * 0.65) + ',' +
        Math.min(255, Math.round(110 + lum * 0.6)) + ')';
    }
    for (i = 0; i < names.length; i++) jobs.push({ into: atlas.frames, map: PKS_PALETTE, name: names[i] });
    for (i = 0; i < names.length; i++) {
      if (PKS_UNIT_ART.test(names[i])) {
        jobs.push({ into: atlas.flash, map: flash, name: names[i] });
        jobs.push({ into: atlas.slow, map: slow, name: names[i] });
      }
    }
    pksTintJobs(atlas, jobs);
    var x = 0, y = 0, rowH = 0;
    for (i = 0; i < jobs.length; i++) {
      var sp = PKS_SPRITES[jobs[i].name];
      if (x + sp.w > WIDTH) {
        x = 0;
        y += rowH + 1;
        rowH = 0;
      }
      jobs[i].into[jobs[i].name] = { x: x, y: y, w: sp.w, h: sp.h };
      x += sp.w + 1;
      rowH = Math.max(rowH, sp.h);
    }
    var height = 1;
    while (height < y + rowH) height *= 2;
    atlas.canvas = makeCanvas(WIDTH, height);
    var ctx = atlas.canvas.getContext('2d');
    for (i = 0; i < jobs.length; i++) {
      var rows = PKS_SPRITES[jobs[i].name].rows;
      var map = jobs[i].map;
      var at = jobs[i].into[jobs[i].name];
      for (j = 0; j < rows.length; j++) {
        var row = rows[j];
        var start = 0;
        for (c = 1; c <= row.length; c++) {
          if (c === row.length || row.charAt(c) !== row.charAt(start)) {
            if (row.charAt(start) !== '.') {
              ctx.fillStyle = map[row.charAt(start)];
              ctx.fillRect(at.x + start, at.y + j, c - start, 1);
            }
            start = c;
          }
        }
      }
    }
    return atlas;
  }

  // ── src/render.js ──

  // ── render: draws a sim on the 320x180 canvas, 1 of 3 parts: the frame, the field, the helpers ──

  var PKS_DECOM = 'decom';
  var PKS_FX_MAX = 160;
  var PKS_FLOOR_RIGHT = PKS_FIELD_X + PKS_COLS * PKS_CELL;  // 312: the 8 px margin starts here
  var PKS_BAR_X = 150;          // the surge progress bar on the top strip
  var PKS_BAR_Y = 7;
  var PKS_BAR_W = 150;
  var PKS_SHIFT_STEPS = pksSteps(PKS_SHIFT_TIME);
  var PKS_SLIDE_STEPS = pksSteps(PKS_SLIDE_TIME);
  var PKS_SHOT_ART = { drop: 'shot-drop', tar: 'shot-tar', phish: 'shot-phish', volley: 'shot-boss', decrypt: 'shot-decrypt' };
  var PKS_BITE_STATES = { biting: true, throwing: true, casting: true };
  var PKS_BOOM_ART = ['fx-boom0', 'fx-boom1', 'fx-boom2', 'fx-boom3'];
  var PKS_SURGE_ART = ['fx-surge0', 'fx-surge1', 'fx-surge2'];
  var PKS_SPLASH_ART = ['fx-splash0', 'fx-splash1', 'fx-splash2'];
  var PKS_ARC_ART = ['fx-arc0', 'fx-arc1'];
  var PKS_AURA_ART = { amplifier: 'fx-aura-amp', hydra: 'fx-aura-heal' };
  var PKS_DEF_ART = pksDefArt();
  var PKS_ENM_ART = pksEnemyArt();
  var PKS_BOSS_ART = [PKS_ENM_ART.boss, pksPoses('boss2-', 'cast'), pksPoses('boss3-', 'cast')];
  var PKS_GEN_ART = [null, PKS_ENM_ART.replicator, pksPoses('enm-replica2-', 'bite'), pksPoses('enm-replica3-', 'bite')];
  var PKS_BIG_ENEMY = pksBigEnemies();
  var PKS_TILE_ART = pksZoneArt('tile-z', ['-a', '-b']);
  var PKS_BACKDROP_ART = pksZoneArt('backdrop-z', ['']);
  var PKS_GLYPHS = {
    '+': '000010111010000', '-': '000000111000000', '0': '111101101101111', '1': '010110010010111',
    '2': '111001111100111', '3': '111001111001111', '4': '101101111001001', '5': '111100111001111',
    '6': '111100111101111', '7': '111001010010010', '8': '111101111101111', '9': '111101111001111'
  };

  function pksDefArt() {
    var art = {};
    for (var i = 0; i < PKS_DEFENDERS.length; i++) {
      var id = PKS_DEFENDERS[i].id;
      var fire = 'def-' + id + '-fire';
      art[id] = ['def-' + id + '-0', 'def-' + id + '-1', pksOwn(PKS_SPRITES, fire) ? fire : null];
    }
    return art;
  }

  function pksEnemyArt() {
    var art = { boss: pksPoses('boss-', 'cast') };
    for (var i = 0; i < PKS_ENEMIES.length; i++) art[PKS_ENEMIES[i].id] = pksPoses('enm-' + PKS_ENEMIES[i].id + '-', 'bite');
    return art;
  }

  function pksPoses(prefix, act) {
    return [prefix + 'walk0', prefix + 'walk1', prefix + act + '0', prefix + act + '1'];
  }

  function pksBigEnemies() {
    var big = {};
    for (var i = 0; i < PKS_ENEMIES.length; i++) {
      if (PKS_SPRITES[PKS_ENM_ART[PKS_ENEMIES[i].id][0]].h > 24) big[PKS_ENEMIES[i].id] = true;
    }
    return big;
  }

  function pksZoneArt(prefix, suffixes) {
    var out = [];
    for (var z = 1; pksOwn(PKS_SPRITES, prefix + z + suffixes[0]); z++) {
      var names = [];
      for (var i = 0; i < suffixes.length; i++) names.push(prefix + z + suffixes[i]);
      out.push(names);
    }
    return out;
  }

  function pksZoneNames(table, zone) {
    return table[zone - 1] || table[0];
  }

  function pksBossArt(tier) {
    var row = PKS_BOSS_TIERS[tier - 1];
    var body = row && row.body ? row.body : 1;
    return PKS_BOSS_ART[body - 1] || PKS_BOSS_ART[0];
  }

  function pksOwn(map, key) {
    return Object.prototype.hasOwnProperty.call(map, key);
  }


  function pksCellAt(px, py) {
    var col = Math.floor((px - PKS_FIELD_X) / PKS_CELL);
    var lane = Math.floor((py - PKS_FIELD_Y) / PKS_CELL);
    if (!(col >= 0 && col < PKS_COLS && lane >= 0 && lane < PKS_LANES)) return null;
    return { lane: lane, col: col };
  }

  function pksCellRect(lane, col) {
    return { x: PKS_FIELD_X + col * PKS_CELL, y: PKS_FIELD_Y + lane * PKS_CELL, w: PKS_CELL, h: PKS_CELL };
  }

  function pksIconName(id) {
    if (id === PKS_DECOM) return 'icon-decom';
    if (pksOwn(PKS_DEF_ART, id)) return PKS_DEF_ART[id][0];
    if (pksOwn(PKS_ENM_ART, id)) return PKS_ENM_ART[id][0];
    return null;
  }

  function pksDrawIcon(ctx, atlas, name, x, y, scale) {
    if (!pksOwn(atlas.frames, name)) return false;
    var f = atlas.frames[name];
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(atlas.canvas, f.x, f.y, f.w, f.h, Math.round(x), Math.round(y), f.w * scale, f.h * scale);
    return true;
  }

  function pksLaneY(lane) {
    return PKS_FIELD_Y + lane * PKS_CELL;
  }

  function pksUnitX(x) {
    return PKS_FIELD_X + x * PKS_CELL;
  }


  function pksBlit(ctx, atlas, set, name, x, y) {
    var f = set[name];
    ctx.drawImage(atlas.canvas, f.x, f.y, f.w, f.h, Math.round(x), Math.round(y), f.w, f.h);
  }

  function pksRect(ctx, color, x, y, w, h) {
    ctx.fillStyle = color;
    ctx.fillRect(Math.round(x), Math.round(y), w, h);
  }

  function pksHpBar(ctx, x, y, w, share) {
    pksRect(ctx, PKS_PALETTE.k, x - 1, y - 1, w + 2, 4);
    var color = PKS_PALETTE.r;
    if (share > 0.5) color = PKS_PALETTE.G;
    else if (share > 0.25) color = PKS_PALETTE.y;
    pksRect(ctx, color, x, y, Math.max(1, Math.round(w * share)), 2);
  }

  function pksShieldBar(ctx, x, y, w, share) {
    pksRect(ctx, PKS_PALETTE.k, x - 1, y - 1, w + 2, 4);
    pksRect(ctx, PKS_PALETTE.Q, x, y, w, 2);
    pksRect(ctx, PKS_PALETTE.q, x, y, Math.max(1, Math.round(w * share)), 2);
  }

  function pksChevron(ctx, color, x, y) {
    pksRect(ctx, color, x, y, 1, 1);
    pksRect(ctx, color, x - 1, y + 1, 3, 1);
  }

  function pksDrawText(ctx, text, x, y, color) {
    x = Math.round(x);
    y = Math.round(y);
    for (var pass = 0; pass < 2; pass++) {
      ctx.fillStyle = pass === 0 ? PKS_PALETTE.k : color || PKS_PALETTE.y;
      for (var c = 0; c < text.length; c++) {
        var glyph = PKS_GLYPHS[text.charAt(c)];
        for (var i = 0; i < 15; i++) {
          if (glyph.charAt(i) === '1') ctx.fillRect(x + c * 4 + i % 3 + 1 - pass, y + Math.floor(i / 3) + 1 - pass, 1, 1);
        }
      }
    }
  }


  function pksRender(ctx, atlas, sim, view) {
    ctx.imageSmoothingEnabled = false;
    ctx.globalAlpha = 1;
    pksDrawStrip(ctx, atlas, sim);
    pksDrawFloor(ctx, atlas, sim);
    var fogX = sim.level.fog > 0 ? PKS_COLS - sim.level.fog : PKS_SHOT_END;
    var i, e;
    pksDrawAuras(ctx, atlas, sim, fogX);
    var down = pksOutageLane(sim);
    for (var lane = 0; lane < PKS_LANES; lane++) {
      for (i = 0; i < sim.defenders.length; i++) {
        if (sim.defenders[i].lane === lane) pksDrawDefender(ctx, atlas, sim, sim.defenders[i]);
      }
      if (lane === down) pksDrawOutage(ctx, atlas, sim, lane);
      for (var big = 1; big >= 0; big--) {
        for (i = 0; i < sim.enemies.length; i++) {
          e = sim.enemies[i];
          if (e.tier === 0 && pksDrawLane(e) === lane && e.x <= fogX && (PKS_BIG_ENEMY[e.type] ? 1 : 0) === big) {
            pksDrawEnemy(ctx, atlas, sim, e);
          }
        }
      }
    }
    pksDrawArming(ctx, sim);
    for (i = 0; i < sim.enemies.length; i++) {
      if (sim.enemies[i].tier > 0 && sim.enemies[i].x <= fogX) pksDrawEnemy(ctx, atlas, sim, sim.enemies[i]);
    }
    pksDrawShimmers(ctx, atlas, sim);
    pksDrawDark(ctx, atlas, sim);
    pksDrawBeams(ctx, atlas, sim);
    pksDrawShots(ctx, atlas, sim);
    pksDrawShells(ctx, atlas, sim);
    for (i = 0; i < view.fx.length; i++) {
      if (view.fx[i].age >= 0 && view.fx[i].age < view.fx[i].life) pksDrawFx(ctx, atlas, sim, view.fx[i]);
    }
    pksDrawPointer(ctx, atlas, view);
    ctx.globalAlpha = 1;
  }

  function pksDrawStrip(ctx, atlas, sim) {
    var lv = sim.level;
    var backdrop = pksZoneNames(PKS_BACKDROP_ART, lv.zone)[0];
    var x, i;
    for (x = 0; x < PKS_W; x += PKS_CELL) pksBlit(ctx, atlas, atlas.frames, backdrop, x, 0);
    var total = Math.max(1, lv.spawns.length);
    var warn = sim.warned > sim.surged;
    pksRect(ctx, PKS_PALETTE.k, PKS_BAR_X - 1, PKS_BAR_Y - 1, PKS_BAR_W + 2, 7);
    pksRect(ctx, PKS_PALETTE.A, PKS_BAR_X, PKS_BAR_Y, PKS_BAR_W, 5);
    pksRect(ctx, warn ? PKS_PALETTE.o : PKS_PALETTE.G, PKS_BAR_X, PKS_BAR_Y, Math.round(PKS_BAR_W * sim.spawnIndex / total), 5);
    var blinkOn = Math.floor(sim.tick / 8) % 2 === 0;
    var before = 0;
    for (i = 0; i < lv.surges.length; i++) {
      while (before < lv.spawns.length && lv.spawns[before].t < lv.surges[i]) before++;
      if (i < sim.surged) ctx.globalAlpha = 0.35;
      else if (i < sim.warned && !blinkOn) continue;
      pksBlit(ctx, atlas, atlas.frames, 'icon-surge', PKS_BAR_X + Math.round(PKS_BAR_W * before / total) - 4, PKS_BAR_Y - 1);
      ctx.globalAlpha = 1;
    }
  }

  function pksDrawFloor(ctx, atlas, sim) {
    var lv = sim.level;
    var tiles = pksZoneNames(PKS_TILE_ART, lv.zone);
    var lane, col, i, y;
    for (lane = 0; lane < PKS_LANES; lane++) {
      y = pksLaneY(lane);
      var state = sim.breakers[lane];
      pksBlit(ctx, atlas, atlas.frames, state === 'tripped' ? 'rack-hit' : 'rack-ok', 0, y);
      if (state !== 'off') pksBlit(ctx, atlas, atlas.frames, state === 'armed' ? 'breaker-armed' : 'breaker-tripped', 13, y + 11);
      for (col = 0; col < PKS_COLS; col++) {
        var tray = false;
        for (i = 0; i < lv.blocked.length; i++) {
          if (lv.blocked[i].lane === lane && lv.blocked[i].col === col) tray = true;
        }
        pksBlit(ctx, atlas, atlas.frames, tray ? 'tile-tray' : tiles[(col + lane) % 2], pksUnitX(col), y);
      }
    }
    pksDrawRuleTiles(ctx, atlas, sim);
    if (lv.fog > 0) {
      var first = PKS_COLS - lv.fog;
      for (lane = 0; lane < PKS_LANES; lane++) {
        y = pksLaneY(lane);
        pksBlit(ctx, atlas, atlas.frames, 'fog-edge', pksUnitX(first) - 16, y);
        for (col = first; col < PKS_COLS; col++) pksBlit(ctx, atlas, atlas.frames, 'fog', pksUnitX(col), y);
      }
    }
    ctx.globalAlpha = 0.65;
    for (lane = 0; lane < PKS_LANES; lane++) {
      if (sim.breakers[lane] === 'off') pksRect(ctx, PKS_PALETTE.k, 0, pksLaneY(lane), PKS_FLOOR_RIGHT, PKS_CELL);
    }
    ctx.globalAlpha = 1;
    pksRect(ctx, PKS_PALETTE.k, PKS_FLOOR_RIGHT, PKS_FIELD_Y, PKS_W - PKS_FLOOR_RIGHT, PKS_H - PKS_FIELD_Y);
  }

  function pksDrawLane(e) {
    return e.shift * 2 > PKS_SHIFT_STEPS ? e.from : e.lane;
  }

  // ── src/render-units.js ──

  // ── render-units: render, 2 of 3 parts: defenders, enemies, bosses, auras, beams, shots and shells ──

  var PKS_ARM_DX = 8;           // the arming bar of a trap: a cyan bar over its cell,
  var PKS_ARM_DY = 9;           // below the HP bar (dy 1..4), above the shut chest;
  var PKS_ARM_W = 16;           // it fills as the trap arms
  var PKS_ARMED_LIFE = 30;      // steps of the full bar blinking once a trap is armed
  var PKS_LEAP_SPAN = 0.5 + PKS_REACH + 0.25;
  var PKS_LEAP_HEIGHT = 14;     // px at the top of the arc
  var PKS_THROW_HEIGHT = 22;    // px at the top of a thrown Bot's flight
  var PKS_KNOCK_HEIGHT = 6;     // px at the top of a knockback's hop
  var PKS_SHELL_HEIGHT = 28;    // px at the top of a Batch Job shell's arc
  var PKS_AURA_ALPHA = 0.4;
  var PKS_BLINK_ALPHA = 0.5;    // a Glitch while it blinks
  var PKS_AT = { x: 0, y: 0, alpha: 1 };  // pksEnemyAt's result (scratch, not state)

  function pksDrawDefender(ctx, atlas, sim, d) {
    var art = PKS_DEF_ART[d.type];
    var name;
    if (d.fire > 0 && art[2]) name = art[2];
    else if (d.kind === 'trap') name = art[d.state === 'armed' ? 1 : 0];
    else if (d.kind === 'instant') name = art[Math.floor(d.anim / 6) % 2];
    else name = art[Math.floor(d.anim / 30) % 2];
    var x = pksUnitX(d.col);
    var y = pksLaneY(d.lane);
    var set = d.flash > 0 ? atlas.flash : atlas.frames;
    if (d.off > 0) {
      ctx.globalAlpha = 0.55;
      pksBlit(ctx, atlas, atlas.slow, name, x + 4, y + 6);
      ctx.globalAlpha = 1;
      pksBlit(ctx, atlas, atlas.frames, 'icon-lock', x + 20, y + 4);
    } else {
      if (d.enc > 0 && Math.floor(d.enc / 8) % 2 === 0) set = atlas.slow;
      pksBlit(ctx, atlas, set, name, x + 4, y + 6);
      if (d.jammed) pksBlit(ctx, atlas, atlas.frames, 'fx-jam', x + 4, y + 6);
      if (d.boosted) pksChevron(ctx, PKS_PALETTE.s, x + 27, y + 3);
    }
    if (d.hp < d.maxHp) {
      pksHpBar(ctx, x + 8, y + 2, 16, d.hp / d.maxHp);
      if (d.healed === sim.tick) pksBlit(ctx, atlas, atlas.frames, 'fx-heal', x + 22, y + 12 - Math.floor(sim.tick % 24 / 3));
    }
  }

  function pksDrawArming(ctx, sim) {
    for (var i = 0; i < sim.defenders.length; i++) {
      var d = sim.defenders[i];
      if (d.kind !== 'trap' || d.t === 0) continue;
      var arm = pksSteps(PKS_DEF[d.type].arm);
      var rearm = pksSteps(PKS_DEF[d.type].rearm || 0);
      var total = rearm > 0 && d.anim + d.t >= arm + rearm ? rearm : arm;
      var x = pksUnitX(d.col) + PKS_ARM_DX;
      var y = pksLaneY(d.lane) + PKS_ARM_DY;
      pksRect(ctx, PKS_PALETTE.k, x - 1, y - 1, PKS_ARM_W + 2, 4);
      pksRect(ctx, PKS_PALETTE.C, x, y, PKS_ARM_W, 2);
      pksRect(ctx, PKS_PALETTE.c, x, y, Math.round(PKS_ARM_W * (1 - d.t / total)), 2);
    }
  }

  function pksEnemyAt(e) {
    var x = e.x;
    var y = pksLaneY(e.lane);
    var alpha = e.cloaked ? 0.35 : 1;
    if (e.shift > 0) y += (pksLaneY(e.from) - y) * e.shift / PKS_SHIFT_STEPS;
    if (e.state === 'leaping') {
      var t = (e.x - e.leapTo) / PKS_LEAP_SPAN;
      y -= PKS_LEAP_HEIGHT * 4 * t * (1 - t);
    }
    if (e.move > 0) {
      var s = e.move / PKS_SLIDE_STEPS;
      x += (e.moveFrom - e.x) * s;
      if (e.type === 'glitch') alpha = PKS_BLINK_ALPHA;
      else y -= (e.moveFrom > e.x ? PKS_THROW_HEIGHT : PKS_KNOCK_HEIGHT) * 4 * s * (1 - s);
    }
    PKS_AT.x = pksUnitX(x);
    PKS_AT.y = y;
    PKS_AT.alpha = alpha;
  }

  function pksDrawAuras(ctx, atlas, sim, fogX) {
    ctx.globalAlpha = PKS_AURA_ALPHA;
    for (var i = 0; i < sim.enemies.length; i++) {
      var e = sim.enemies[i];
      if (e.aura === 0 || !pksOwn(PKS_AURA_ART, e.type) || e.x > fogX) continue;
      pksEnemyAt(e);
      pksBlit(ctx, atlas, atlas.frames, PKS_AURA_ART[e.type], PKS_AT.x - 24, PKS_AT.y - 6);
    }
    ctx.globalAlpha = 1;
  }

  function pksDrawEnemy(ctx, atlas, sim, e) {
    var frame = Math.floor(e.anim / 12) % 2;
    pksEnemyAt(e);
    var cx = PKS_AT.x;
    var y = PKS_AT.y;
    var set = atlas.frames;
    if (e.flash > 0) set = atlas.flash;
    else if (e.slow > 0) set = atlas.slow;
    ctx.globalAlpha = PKS_AT.alpha;
    if (e.tier > 0) {
      var body = pksBossArt(e.tier)[(e.cast > 0 ? 2 : 0) + frame];
      pksBlit(ctx, atlas, set === atlas.frames ? pksBossSet(atlas, e.tier, body) : set, body, cx - 24, y - 16);
      if (e.shield > 0) pksBlit(ctx, atlas, atlas.frames, 'fx-shield-boss', cx - 24, y - 16);
      if (e.frozen > 0) pksBlit(ctx, atlas, atlas.frames, 'fx-freeze', cx - 12, y + 2);
      ctx.globalAlpha = 1;
      pksHpBar(ctx, cx - 16, y - 19, 32, e.hp / e.maxHp);
      if (e.shield > 0) pksShieldBar(ctx, cx - 16, y - 24, 32, e.shield / e.maxShield);
      if (e.amped) pksChevron(ctx, PKS_PALETTE.o, cx + 19, y - 21);
      return;
    }
    var art = e.gen > 1 ? PKS_GEN_ART[e.gen] : PKS_ENM_ART[e.type];
    var name = art[(PKS_BITE_STATES[e.state] ? 2 : 0) + frame];
    var sp = PKS_SPRITES[name];
    pksBlit(ctx, atlas, set, name, cx - sp.w / 2, y + 30 - sp.h);
    if (e.frozen > 0) pksBlit(ctx, atlas, atlas.frames, 'fx-freeze', cx - 12, y + 6);
    if (e.shield > 0) pksBlit(ctx, atlas, atlas.frames, 'fx-shield', cx - 12, y + 6);
    ctx.globalAlpha = 1;
    if (e.shield > 0) pksShieldBar(ctx, cx - 8, y + 2, 16, e.shield / e.maxShield);
    if (e.amped) pksChevron(ctx, PKS_PALETTE.o, cx + 10, y + 3);
    if (e.mended === sim.tick) {
      var py = y + 8 - Math.floor(sim.tick % 24 / 4);
      pksRect(ctx, PKS_PALETTE.t, cx - 12, py + 1, 3, 1);
      pksRect(ctx, PKS_PALETTE.t, cx - 11, py, 1, 3);
    }
  }

  function pksDrawBeams(ctx, atlas, sim) {
    var f = atlas.frames.beam;
    for (var i = 0; i < sim.defenders.length; i++) {
      var d = sim.defenders[i];
      if (d.kind !== 'beam' || d.fire === 0) continue;
      ctx.globalAlpha = Math.min(1, d.fire / 8);
      var y = pksLaneY(d.lane) + 11;
      for (var x = pksUnitX(d.col) + 28; x < PKS_FLOOR_RIGHT; x += f.w) {
        var w = Math.min(f.w, PKS_FLOOR_RIGHT - x);
        ctx.drawImage(atlas.canvas, f.x, f.y, w, f.h, x, y, w, f.h);
      }
    }
    ctx.globalAlpha = 1;
  }

  function pksDrawShots(ctx, atlas, sim) {
    for (var i = 0; i < sim.shots.length; i++) {
      var s = sim.shots[i];
      var name = PKS_SHOT_ART[s.kind];
      pksBlit(ctx, atlas, atlas.frames, name, pksUnitX(s.x) - PKS_SPRITES[name].w / 2, pksLaneY(s.lane) + 13);
    }
  }

  function pksDrawShells(ctx, atlas, sim) {
    for (var i = 0; i < sim.shells.length; i++) {
      var s = sim.shells[i];
      var p = 1 - s.t / s.flight;
      var x = pksUnitX(s.from + (s.to - s.from) * p);
      var y = pksLaneY(s.lane);
      ctx.globalAlpha = 0.45;
      pksRect(ctx, PKS_PALETTE.k, x - 3, y + 27, 6, 2);
      ctx.globalAlpha = 1;
      pksBlit(ctx, atlas, atlas.frames, 'shot-shell', x - 4, y + 13 - PKS_SHELL_HEIGHT * 4 * p * (1 - p));
    }
  }

  // ── src/render-fx.js ──

  // ── render-fx: render, 3 of 3 parts: the view, its passing effects and the pointer ──

  var PKS_HIT_DX = { drop: -14, tar: -14, decrypt: -14, phish: -4, volley: -4 };  // spark left of an enemy, on a defender
  var PKS_STEAL_GROUP = 20;     // steps a Keylogger's "-N" pip keeps adding what it steals
  var PKS_UPKEEP_X = 6;         // the upkeep pip: on the rack of lane 1, under the
  var PKS_UPKEEP_Y = 26;        // trickle's pip on the strip


  function pksNewView() {
    return { cursor: null, ghost: null, fx: [], tick: 0, ring: 0, events: null, seen: 0 };
  }

  function pksViewStep(view) {
    view.tick++;
    for (var i = 0; i < view.fx.length; i++) {
      if (view.fx[i].age < view.fx[i].life) view.fx[i].age++;
    }
  }

  function pksViewEvents(view, sim) {
    if (view.events !== sim.events) {
      view.events = sim.events;
      view.seen = 0;
    }
    for (var i = view.seen; i < sim.events.length; i++) pksEventFx(view, sim.events[i]);
    view.seen = sim.events.length;
  }

  function pksAddFx(view, kind, x, y, life, delay) {
    var list = view.fx;
    var fx = null;
    for (var i = 0; i < list.length && !fx; i++) {
      if (list[i].age >= list[i].life) fx = list[i];
    }
    if (!fx && list.length < PKS_FX_MAX) {
      fx = {};
      list.push(fx);
    } else if (!fx) {
      fx = list[view.ring];
      view.ring = (view.ring + 1) % PKS_FX_MAX;
    }
    fx.kind = kind;
    fx.x = x;
    fx.y = y;
    fx.age = 0 - delay;
    fx.life = life;
    fx.lane = 0;
    fx.text = '';
    fx.color = '';
    fx.art = '';
    fx.to = 0;
    fx.id = 0;
    fx.n = 0;
    fx.path = null;
    return fx;
  }

  function pksDecal(view, art, x, y, life) {
    pksAddFx(view, 'decal', x, y, life, 0).art = art;
  }

  function pksEventFx(view, ev) {
    var x, y, i;
    switch (ev.type) {
      case 'hit':
        pksAddFx(view, 'spark', pksUnitX(ev.x) + PKS_HIT_DX[ev.kind], pksLaneY(ev.lane) + 12, 6, 0);
        break;
      case 'kill':
        if (ev.enemy === 'boss' || PKS_BIG_ENEMY[ev.enemy]) pksAddFx(view, 'boom', pksUnitX(ev.x) - 16, pksLaneY(ev.lane) - 8, 24, 0);
        else pksAddFx(view, 'puff', pksUnitX(ev.x) - 16, pksLaneY(ev.lane), 8, 0);
        break;
      case 'blast':
        pksBlastFx(view, ev);
        break;
      case 'pulse':
        pksAddFx(view, 'ring', pksUnitX(ev.col + 0.5), pksLaneY(ev.lane) + 16, 12, 0);
        break;
      case 'freeze':
        pksAddFx(view, 'flash', 0, 0, 24, 0);
        break;
      case 'breaker':
        pksAddFx(view, 'sweep', 0, pksLaneY(ev.lane), 36, 0).lane = ev.lane;
        pksAddFx(view, 'rack', 0, pksLaneY(ev.lane), 30, 0);
        break;
      case 'lose':
        pksAddFx(view, 'rack', 0, pksLaneY(ev.lane), 30, 0);
        break;
      case 'surgeWarn':
        pksAddFx(view, 'edge', PKS_FLOOR_RIGHT, 0, pksSteps(PKS_SURGE_WARN), 0).color = PKS_PALETTE.o;
        break;
      case 'surge':
        pksAddFx(view, 'edge', PKS_FLOOR_RIGHT, 0, 60, 0).color = PKS_PALETTE.r;
        break;
      case 'produce':
        pksAddFx(view, 'pip', pksUnitX(ev.col) + 6, pksLaneY(ev.lane) + 4, 40, 0).text = '+' + ev.amount;
        break;
      case 'trickle':
        pksAddFx(view, 'pip', 6, 10, 40, 0).text = '+' + ev.amount;
        break;
      case 'placed':
        pksAddFx(view, 'place', pksUnitX(ev.col), pksLaneY(ev.lane), 10, 0);
        break;
      case 'removed':
        pksAddFx(view, 'puff', pksUnitX(ev.col), pksLaneY(ev.lane), 8, 0);
        break;
      case 'destroyed':
        if (ev.why !== 'spent') pksAddFx(view, 'puff', pksUnitX(ev.col), pksLaneY(ev.lane), 8, 0);
        break;
      case 'armed':
        pksAddFx(view, 'spark', pksUnitX(ev.col) + 20, pksLaneY(ev.lane) + 6, 12, 0);
        pksAddFx(view, 'armed', pksUnitX(ev.col) + PKS_ARM_DX, pksLaneY(ev.lane) + PKS_ARM_DY, PKS_ARMED_LIFE, 0);
        break;
      case 'cleared':
        pksAddFx(view, 'glint', pksUnitX(ev.col) + 12, pksLaneY(ev.lane) + 4, 24, 0);
        break;
      case 'cloak':
        x = pksUnitX(ev.x);
        y = pksLaneY(ev.lane);
        if (ev.on) pksAddFx(view, 'puff', x - 16, y, 8, 0);
        else pksAddFx(view, 'spark', x - 4, y + 12, 10, 0);
        break;
      case 'morph':
        pksAddFx(view, 'puff', pksUnitX(ev.x) - 16, pksLaneY(ev.from), 8, 0);
        break;
      case 'summon':
        for (i = 0; i < 2; i++) pksAddFx(view, 'puff', pksUnitX(ev.x + 0.6 + i * 0.5) - 16, pksLaneY(ev.lane), 8, i * 3);
        break;
      default:
        pksLateEventFx(view, ev);
    }
  }

  function pksLateEventFx(view, ev) {
    var fx, i;
    switch (ev.type) {
      case 'steal':
        pksStealFx(view, ev);
        break;
      case 'detonate':
        pksBoomArea(view, ev.lane, ev.col);
        break;
      case 'wipe':
        pksDecal(view, 'fx-wipe', pksUnitX(ev.col), pksLaneY(ev.lane), 18);
        break;
      case 'release':
        pksAddFx(view, 'puff', pksUnitX(ev.x) - 16, pksLaneY(ev.lane), 8, 0);
        break;
      case 'throw':
        pksAddFx(view, 'spark', pksUnitX(ev.x) - 4, pksLaneY(ev.lane) + 6, 8, 0);
        break;
      case 'split':
        for (i = 0; i < 2; i++) pksAddFx(view, 'puff', pksUnitX(ev.x + i * 0.4) - 16, pksLaneY(ev.lane), 8, i * 3);
        break;
      case 'shieldBreak':
        pksDecal(view, 'fx-shield-break', pksUnitX(ev.x) - 12, pksLaneY(ev.lane) + 6, 14);
        break;
      case 'blink':
        pksDecal(view, 'fx-blink', pksUnitX(ev.x) - 16, pksLaneY(ev.lane), 12);
        break;
      case 'trace':
        fx = pksAddFx(view, 'trace', pksUnitX(ev.col) + 27, pksLaneY(ev.lane) + 17, 10, 0);
        fx.to = Math.round(pksUnitX(ev.x)) - 6;
        pksAddFx(view, 'spark', pksUnitX(ev.x) - 14, pksLaneY(ev.lane) + 12, 6, 0);
        break;
      case 'splash':
        pksAddFx(view, 'splash', pksUnitX(ev.x) - 16, pksLaneY(ev.lane), 15, 0);
        break;
      case 'knock':
        pksDecal(view, 'fx-knock', pksUnitX(ev.from) - 16, pksLaneY(ev.lane), 12);
        break;
      case 'arc':
        fx = pksAddFx(view, 'arc', pksUnitX(ev.col) + 27, pksLaneY(ev.lane) + 17, 10, 0);
        fx.lane = ev.lane;
        fx.path = ev.path;
        for (i = 0; i < ev.path.length; i++) pksAddFx(view, 'spark', pksUnitX(ev.path[i].x) - 4, pksLaneY(ev.path[i].lane) + 12, 8, 0);
        break;
      case 'pull':
        pksDecal(view, 'fx-pull', pksUnitX(ev.x) - 16, pksLaneY(ev.from), 16);
        break;
      case 'reflect':
        pksAddFx(view, 'spark', pksUnitX(ev.x) - 4, pksLaneY(ev.lane) + 12, 8, 0);
        break;
      case 'restore':
        pksDecal(view, 'fx-restore', pksUnitX(ev.col), pksLaneY(ev.lane), 20);
        break;
      case 'scrub':
        pksAddFx(view, 'flash', 0, 0, 16, 0).color = PKS_PALETTE.w;
        pksAddFx(view, 'ring', pksUnitX(ev.col + 0.5), pksLaneY(ev.lane) + 16, 12, 0);
        break;
      default:
        pksRuleEventFx(view, ev);
    }
  }

  function pksRuleEventFx(view, ev) {
    var fx;
    switch (ev.type) {
      case 'emerge':
        pksAddFx(view, 'puff', pksUnitX(ev.col), pksLaneY(ev.lane), 8, 0);
        break;
      case 'cross':
        pksAddFx(view, 'ring', pksUnitX(ev.col + 0.5), pksLaneY(ev.from) + 16, 12, 0);
        break;
      case 'upkeep':
        fx = pksAddFx(view, 'pip', PKS_UPKEEP_X, PKS_UPKEEP_Y, 40, 0);
        fx.text = ev.amount ? '-' + ev.amount : '0';
        fx.color = ev.amount ? PKS_PALETTE.x : PKS_PALETTE.w;
        fx.art = 'icon-upkeep';
        break;
      case 'shieldUp':
        pksDecal(view, 'fx-shield-boss', pksUnitX(ev.x) - 24, pksLaneY(ev.lane) - 16, 20);
        break;
      case 'bossSplit':
        pksAddFx(view, 'flash', 0, 0, 12, 0).color = PKS_PALETTE.f;
        pksAddFx(view, 'ring', pksUnitX(ev.x), pksLaneY(ev.lane) + 16, 16, 0);
        break;
    }
  }

  function pksStealFx(view, ev) {
    for (var i = 0; i < view.fx.length; i++) {
      var f = view.fx[i];
      if (f.kind === 'pip' && f.id === ev.id && f.age >= 0 && f.age < PKS_STEAL_GROUP) {
        f.n += ev.amount;
        f.text = '-' + f.n;
        return;
      }
    }
    var fx = pksAddFx(view, 'pip', pksUnitX(ev.x) - 4, pksLaneY(ev.lane) + 2, 30, 0);
    fx.id = ev.id;
    fx.n = ev.amount;
    fx.text = '-' + ev.amount;
    fx.color = PKS_PALETTE.x;
  }

  function pksBlastFx(view, ev) {
    var effect = PKS_DEF[ev.def].effect;
    var c;
    if (effect === 'blast') {
      pksBoomArea(view, ev.lane, ev.col);
    } else if (effect === 'lane') {
      for (c = 0; c < PKS_COLS; c++) pksAddFx(view, 'boom', pksUnitX(c), pksLaneY(ev.lane), 16, c * 2);
    } else {
      pksAddFx(view, 'boom', pksUnitX(ev.col), pksLaneY(ev.lane), 16, 0);
    }
  }

  function pksBoomArea(view, lane, col) {
    for (var l = Math.max(0, lane - 1); l <= Math.min(PKS_LANES - 1, lane + 1); l++) {
      for (var c = Math.max(0, col - 1); c <= Math.min(PKS_COLS - 1, col + 1); c++) {
        pksAddFx(view, 'boom', pksUnitX(c), pksLaneY(l), 16, (l + c) % 2 * 2);
      }
    }
  }


  function pksDrawFx(ctx, atlas, sim, fx) {
    var F = atlas.frames;
    var fade = 1 - fx.age / fx.life;
    var i;
    switch (fx.kind) {
      case 'spark':
        pksBlit(ctx, atlas, F, 'fx-hit', fx.x, fx.y);
        break;
      case 'boom':
        pksBlit(ctx, atlas, F, PKS_BOOM_ART[Math.floor(fx.age * 4 / fx.life)], fx.x, fx.y);
        break;
      case 'puff':
        ctx.globalAlpha = 0.7;
        pksBlit(ctx, atlas, F, PKS_BOOM_ART[2 + Math.floor(fx.age * 2 / fx.life)], fx.x, fx.y);
        break;
      case 'sweep':
        ctx.globalAlpha = Math.min(1, fade * 2);
        for (i = 0; i < Math.min(PKS_COLS, Math.floor(fx.age / 2) + 1); i++) {
          pksBlit(ctx, atlas, F, PKS_SURGE_ART[(fx.age + i) % 3], pksUnitX(i), fx.y);
        }
        break;
      case 'rack':
        if (Math.floor(fx.age / 4) % 2 === 0) {
          ctx.globalAlpha = 0.6;
          pksRect(ctx, PKS_PALETTE.w, 0, fx.y, PKS_FIELD_X, PKS_CELL);
        }
        break;
      case 'glint':
        ctx.globalAlpha = fade;
        pksBlit(ctx, atlas, F, 'fx-heal', fx.x, fx.y - fx.age / 3);
        break;
      case 'pip':
        ctx.globalAlpha = Math.min(1, fade * 3);
        pksBlit(ctx, atlas, F, fx.art || 'icon-cycles', fx.x, fx.y - fx.age / 4);
        pksDrawText(ctx, fx.text, fx.x + 10, fx.y + 2 - fx.age / 4, fx.color);
        break;
      case 'ring':
        var half = 16 + Math.round(32 * fx.age / fx.life);
        ctx.globalAlpha = fade;
        pksRect(ctx, PKS_PALETTE.c, fx.x - half, fx.y - half, half * 2, 1);
        pksRect(ctx, PKS_PALETTE.c, fx.x - half, fx.y + half - 1, half * 2, 1);
        pksRect(ctx, PKS_PALETTE.c, fx.x - half, fx.y - half, 1, half * 2);
        pksRect(ctx, PKS_PALETTE.c, fx.x + half - 1, fx.y - half, 1, half * 2);
        break;
      case 'flash':
        ctx.globalAlpha = 0.4 * fade;
        pksRect(ctx, fx.color || PKS_PALETTE.c, PKS_FIELD_X, PKS_FIELD_Y, PKS_COLS * PKS_CELL, PKS_LANES * PKS_CELL);
        break;
      case 'place':
        ctx.globalAlpha = fade;
        pksBlit(ctx, atlas, F, 'cursor', fx.x, fx.y);
        break;
      case 'armed':
        ctx.globalAlpha = Math.min(1, fade * 2);
        pksRect(ctx, PKS_PALETTE.k, fx.x - 1, fx.y - 1, PKS_ARM_W + 2, 4);
        pksRect(ctx, Math.floor(fx.age / 4) % 2 === 0 ? PKS_PALETTE.w : PKS_PALETTE.c, fx.x, fx.y, PKS_ARM_W, 2);
        break;
      case 'edge':
        if (Math.floor(fx.age / 10) % 2 === 0) {
          ctx.globalAlpha = Math.min(1, fade * 4);
          for (i = 0; i < PKS_LANES; i++) {
            if (sim.breakers[i] !== 'off') pksRect(ctx, fx.color, fx.x + 2, pksLaneY(i) + 6, 4, PKS_CELL - 12);
          }
        }
        break;
      default:
        pksDrawLateFx(ctx, atlas, fx, fade);
    }
    ctx.globalAlpha = 1;
  }

  function pksDrawLateFx(ctx, atlas, fx, fade) {
    switch (fx.kind) {
      case 'decal':
        ctx.globalAlpha = Math.min(1, fade * 2);
        pksBlit(ctx, atlas, atlas.frames, fx.art, fx.x, fx.y);
        break;
      case 'splash':
        pksBlit(ctx, atlas, atlas.frames, PKS_SPLASH_ART[Math.floor(fx.age * 3 / fx.life)], fx.x, fx.y);
        break;
      case 'trace':
        ctx.globalAlpha = fade;
        pksRect(ctx, PKS_PALETTE.x, fx.x, fx.y, Math.max(1, fx.to - fx.x), 1);
        if (fx.age < 4) {
          pksRect(ctx, PKS_PALETTE.w, fx.x, fx.y - 1, Math.max(1, fx.to - fx.x), 1);
          pksBlit(ctx, atlas, atlas.frames, 'shot-heavy', fx.to - 6, fx.y - 4);
        }
        break;
      case 'arc':
        ctx.globalAlpha = Math.min(1, fade * 2);
        pksDrawArc(ctx, atlas, fx, Math.floor(fx.age / 2) % 2);
        break;
    }
  }

  function pksDrawArc(ctx, atlas, fx, phase) {
    var ax = fx.x;
    var al = fx.lane;
    for (var i = 0; i < fx.path.length; i++) {
      var bx = Math.round(pksUnitX(fx.path[i].x));
      var bl = fx.path[i].lane;
      var flat = bl > al ? al : bl;
      pksBolt(ctx, ax, bx, pksLaneY(flat) + 17, phase);
      var vx = bl > al ? bx : ax;
      for (var l = Math.min(al, bl); l < Math.max(al, bl); l++) {
        pksBlit(ctx, atlas, atlas.frames, PKS_ARC_ART[phase], vx - 16, pksLaneY(l) + 17);
      }
      ax = bx;
      al = bl;
    }
  }

  function pksBolt(ctx, x0, x1, y, phase) {
    var a = Math.min(x0, x1);
    var b = Math.max(x0, x1);
    for (var px = a, k = phase; px < b; px += 4, k++) {
      var w = Math.min(4, b - px);
      var dy = k % 2;
      pksRect(ctx, PKS_PALETTE.q, px, y - 1 + dy, w, 1);
      pksRect(ctx, PKS_PALETTE.w, px, y + dy, w, 1);
    }
  }

  function pksDrawPointer(ctx, atlas, view) {
    var c = view.cursor;
    var g = view.ghost;
    if (c && !(g && g.lane === c.lane && g.col === c.col)) {
      pksBlit(ctx, atlas, atlas.frames, 'cursor', pksUnitX(c.col), pksLaneY(c.lane));
    }
    if (!g) return;
    var x = pksUnitX(g.col);
    var y = pksLaneY(g.lane);
    var name = pksIconName(g.card);
    if (name) {
      ctx.globalAlpha = g.ok ? 0.6 : 0.3;
      pksBlit(ctx, atlas, atlas.frames, name, x + 4, y + 6);
      ctx.globalAlpha = 1;
    }
    pksBlit(ctx, atlas, atlas.frames, g.ok ? 'cursor' : 'cursor-bad', x, y);
  }

  // ── src/render-rules.js ──

  // ── render-rules: render, 4 of 4 parts: the zone rules of levels 51-150 on the field ──

  var PKS_SIGHT_KIND = { shooter: true, sniper: true, mortar: true, knock: true, arc: true, decrypt: true };
  var PKS_HALVES = 2 * PKS_COLS;          // half cells in a lane
  var PKS_LIT = [];                       // the light map: lane * PKS_HALVES + half (scratch)
  var PKS_FIRST = [0, 0, 0, 0, 0];        // the first seeing defender's half per lane (scratch)
  var PKS_DARK_WARN = 0.4;                // the warning's alpha
  var PKS_OUTAGE_WARN = 0.5;
  var PKS_SHIMMER_STEPS = pksSteps(PKS_SHIMMER);
  var PKS_SHIMMER_ART = ['fx-shimmer0', 'fx-shimmer1', 'fx-shimmer2'];

  function pksDrawRuleTiles(ctx, atlas, sim) {
    var R = sim.level.rules;
    if (!R) return;
    var F = atlas.frames;
    var i, c;
    for (i = 0; i < R.hot.length; i++) pksBlit(ctx, atlas, F, 'tile-hot', pksUnitX(R.hot[i].col), pksLaneY(R.hot[i].lane));
    for (i = 0; i < R.rails.length; i++) pksBlit(ctx, atlas, F, 'tile-rail', pksUnitX(R.rails[i].col), pksLaneY(R.rails[i].lane));
    for (i = 0; i < R.express.length; i++) {
      for (c = 0; c < PKS_COLS; c++) pksBlit(ctx, atlas, F, 'tile-express', pksUnitX(c), pksLaneY(R.express[i]));
    }
    for (i = 0; i < R.tunnels.length; i++) pksBlit(ctx, atlas, F, 'tile-tunnel', pksUnitX(R.tunnels[i].col), pksLaneY(R.tunnels[i].lane));
    for (i = 0; i < R.cross.length; i++) {
      var x = R.cross[i];
      pksBlit(ctx, atlas, F, x.to < x.lane ? 'tile-cross-up' : 'tile-cross-down', pksUnitX(x.col), pksLaneY(x.lane));
    }
  }

  function pksDrawShimmers(ctx, atlas, sim) {
    for (var i = 0; i < sim.shimmers.length; i++) {
      var sh = sim.shimmers[i];
      var frame = Math.min(2, Math.max(0, Math.floor((PKS_SHIMMER_STEPS - sh.t) * 3 / PKS_SHIMMER_STEPS)));
      pksBlit(ctx, atlas, atlas.frames, PKS_SHIMMER_ART[frame], pksUnitX(sh.col), pksLaneY(sh.lane));
    }
  }

  function pksOutageLane(sim) {
    return sim.outage && sim.outage.state !== 'clear' ? sim.outage.lane : -1;
  }

  function pksDrawOutage(ctx, atlas, sim, lane) {
    if (sim.outage.state === 'warn') {
      if (Math.floor(sim.tick / 8) % 2 === 1) return;
      ctx.globalAlpha = PKS_OUTAGE_WARN;
    }
    for (var c = 0; c < PKS_COLS; c++) pksBlit(ctx, atlas, atlas.frames, 'fx-outage', pksUnitX(c), pksLaneY(lane));
    ctx.globalAlpha = 1;
  }

  function pksCanLook(sim, d) {
    if (d.off > 0 || d.jammed) return false;
    return !(pksOutageLane(sim) === d.lane && sim.outage.state === 'down');
  }

  function pksLightMap(sim, sight) {
    var reach = Math.round(2 * sight);
    var i, l, h;
    for (i = 0; i < PKS_LANES * PKS_HALVES; i++) PKS_LIT[i] = false;
    for (l = 0; l < PKS_LANES; l++) PKS_FIRST[l] = -1;
    for (i = 0; i < sim.defenders.length; i++) {
      var d = sim.defenders[i];
      var def = PKS_DEF[d.type];
      if (d.hp <= 0 || !PKS_SIGHT_KIND[def.kind] || !pksCanLook(sim, d)) continue;
      var spread = def.spread || 0;
      var from = 2 * d.col + 1;
      for (l = Math.max(0, d.lane - spread); l <= Math.min(PKS_LANES - 1, d.lane + spread); l++) {
        if (PKS_FIRST[l] < 0 || from < PKS_FIRST[l]) PKS_FIRST[l] = from;
        for (h = from; h < Math.min(PKS_HALVES, from + reach); h++) PKS_LIT[l * PKS_HALVES + h] = true;
      }
    }
    for (l = 0; l < PKS_LANES; l++) {
      for (h = 0; h < PKS_FIRST[l]; h++) PKS_LIT[l * PKS_HALVES + h] = true;
    }
  }

  function pksDrawDark(ctx, atlas, sim) {
    var b = sim.blackout;
    if (!b || b.state === 'clear') return;
    if (b.state === 'warn') {
      if (Math.floor(sim.tick / 8) % 2 === 1) return;
      ctx.globalAlpha = PKS_DARK_WARN;
    }
    pksLightMap(sim, sim.level.rules.blackout.sight);
    var f = atlas.frames['fx-dark'];
    for (var l = 0; l < PKS_LANES; l++) {
      for (var c = 0; c < PKS_COLS; c++) {
        var left = !PKS_LIT[l * PKS_HALVES + 2 * c];
        var right = !PKS_LIT[l * PKS_HALVES + 2 * c + 1];
        var x = pksUnitX(c);
        var w = left && right ? PKS_CELL : PKS_CELL / 2;
        if (!left && right) x += PKS_CELL / 2;
        if (left || right) ctx.drawImage(atlas.canvas, f.x, f.y, w, f.h, x, pksLaneY(l), w, f.h);
      }
    }
    ctx.globalAlpha = 1;
  }

  function pksBossSet(atlas, tier, name) {
    var row = PKS_BOSS_TIERS[tier - 1];
    var tint = row && row.hue ? atlas.tints[row.hue] : null;
    return tint && tint[name] ? tint : atlas.frames;
  }

  // ── src/storage.js ──

  // ── storage: the save pks-state (v 1) and the snapshot pks-run of a level in progress ──

  var PKS_SAVE_KEY = 'pks-state';
  var PKS_SAVE_V = 1;
  var PKS_MAX_LOADOUT = pksSlots(PKS_LEVELS);
  var PKS_MET_IDS = pksMetIds();
  var PKS_RUN_KEY = 'pks-run';
  var PKS_RUN_V = 1;
  var PKS_RUN_EVERY = 30;       // seconds of play between snapshots
  var PKS_RUN_TABLES = JSON.stringify([PKS_DEFENDERS, PKS_ENEMIES, PKS_BOSS_TIERS]);
  var PKS_RUN_HASHES = {};
  var PKS_RUN_LISTS = ['cards', 'defenders', 'enemies', 'shots', 'shells', 'shimmers', 'breakers'];
  var PKS_RUN_COUNTS = ['tick', 'time', 'rng', 'cycles', 'trickleT', 'tripped', 'spawnIndex', 'warned', 'surged', 'nextId'];

  function pksMetIds() {
    var ids = [];
    for (var i = 0; i < PKS_ENEMIES.length; i++) ids.push(PKS_ENEMIES[i].id);
    ids.push('boss');
    return ids;
  }

  function pksNewSave() {
    var stars = [];
    for (var i = 0; i < PKS_LEVELS; i++) stars.push(0);
    return { v: 1, unlocked: 1, stars: stars, loadout: [], speed: 1, met: [] };
  }

  function pksIsWhole(value, lo, hi) {
    return typeof value === 'number' && Math.floor(value) === value && value >= lo && value <= hi;
  }

  function pksParseSave(text) {
    var save = pksNewSave();
    var raw;
    try {
      raw = JSON.parse(text);
    } catch (err) {
      return save;
    }
    if (!raw || raw.v !== 1) return save;
    var i;
    if (pksIsWhole(raw.unlocked, 1, PKS_LEVELS)) save.unlocked = raw.unlocked;
    if (Array.isArray(raw.stars)) {
      for (i = 0; i < PKS_LEVELS; i++) {
        if (pksIsWhole(raw.stars[i], 0, 3)) save.stars[i] = raw.stars[i];
      }
    }
    for (i = 0; i < PKS_LEVELS; i++) {
      if (save.stars[i] > 0) save.unlocked = Math.max(save.unlocked, Math.min(PKS_LEVELS, i + 2));
    }
    if (Array.isArray(raw.loadout)) {
      for (i = 0; i < raw.loadout.length && save.loadout.length < PKS_MAX_LOADOUT; i++) {
        var id = raw.loadout[i];
        if (typeof id === 'string' && pksOwn(PKS_DEF, id) && save.loadout.indexOf(id) === -1) save.loadout.push(id);
      }
    }
    if (raw.speed === 2) save.speed = 2;
    if (Array.isArray(raw.met)) save.met = pksMetOf(raw.met, []);
    return save;
  }

  function pksMetOf(a, b) {
    var out = [];
    for (var i = 0; i < PKS_MET_IDS.length; i++) {
      if (a.indexOf(PKS_MET_IDS[i]) !== -1 || b.indexOf(PKS_MET_IDS[i]) !== -1) out.push(PKS_MET_IDS[i]);
    }
    return out;
  }

  function pksSerialize(save) {
    return JSON.stringify({
      v: 1, unlocked: save.unlocked, stars: save.stars, loadout: save.loadout, speed: save.speed, met: save.met
    });
  }

  function pksMergeSaves(mine, stored) {
    var out = {
      v: 1, unlocked: Math.max(mine.unlocked, stored.unlocked), stars: [], loadout: mine.loadout.slice(),
      speed: mine.speed, met: pksMetOf(mine.met, stored.met)
    };
    for (var i = 0; i < PKS_LEVELS; i++) out.stars.push(Math.max(mine.stars[i], stored.stars[i]));
    return out;
  }

  function pksNewerV(text, known) {
    var raw;
    try {
      raw = JSON.parse(text);
    } catch (err) {
      return 0;
    }
    return raw && typeof raw.v === 'number' && Math.floor(raw.v) === raw.v && raw.v > known ? raw.v : 0;
  }

  function pksReadSave(storage) {
    var text;
    try {
      text = storage.getItem(PKS_SAVE_KEY);
    } catch (err) {
      return { state: pksNewSave(), ok: false, error: err, newer: 0 };
    }
    var newer = pksNewerV(text, PKS_SAVE_V);
    return { state: pksParseSave(text), ok: newer === 0, error: null, newer: newer };
  }

  function pksWriteSave(storage, save) {
    var read = pksReadSave(storage);
    var merged = pksMergeSaves(save, read.state);
    if (read.newer) return { state: merged, ok: false, error: null, newer: read.newer };
    try {
      storage.setItem(PKS_SAVE_KEY, pksSerialize(merged));
    } catch (err) {
      return { state: merged, ok: false, error: err, newer: 0 };
    }
    return { state: merged, ok: true, error: null, newer: 0 };
  }

  function pksHighestWon(save) {
    return save.stars[PKS_LEVELS - 1] > 0 ? PKS_LEVELS : save.unlocked - 1;
  }

  function pksOwnedDefenders(save) {
    return pksUnlockedDefenders(pksHighestWon(save));
  }

  function pksRecordWin(save, n, stars) {
    var next = pksMergeSaves(save, save);
    var before = save.stars[n - 1];
    next.stars[n - 1] = Math.max(before, stars);
    next.unlocked = Math.max(save.unlocked, Math.min(PKS_LEVELS, n + 1));
    var owned = pksOwnedDefenders(save);
    var slots = pksSlots(next.unlocked);
    return {
      state: next, level: n, stars: next.stars[n - 1], before: before, improved: stars > before,
      newLevel: next.unlocked > save.unlocked ? next.unlocked : null,
      newDefenders: pksOwnedDefenders(next).slice(owned.length),
      newSlots: slots > pksSlots(save.unlocked) ? slots : null
    };
  }

  function pksRecordMet(save, id) {
    if (save.met.indexOf(id) !== -1 || PKS_MET_IDS.indexOf(id) === -1) return { state: save, added: false };
    var next = pksMergeSaves(save, save);
    next.met = pksMetOf(save.met, [id]);
    return { state: next, added: true };
  }

  function pksLoadoutFor(save, n) {
    var owned = pksOwnedDefenders(save);
    var slots = pksSlots(n);
    if (owned.length <= slots) return { owned: owned, slots: slots, pick: owned.slice(), choose: false };
    var pick = [];
    var i;
    for (i = 0; i < save.loadout.length && pick.length < slots; i++) {
      if (owned.indexOf(save.loadout[i]) !== -1) pick.push(save.loadout[i]);
    }
    for (i = owned.length - 1; pick.length < slots; i--) {
      if (pick.indexOf(owned[i]) === -1) pick.push(owned[i]);
    }
    return { owned: owned, slots: slots, pick: pick, choose: true };
  }


  function pksHash(text) {
    var h = 0x811c9dc5;
    for (var i = 0; i < text.length; i++) {
      h ^= text.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    return ('0000000' + (h >>> 0).toString(16)).slice(-8);
  }

  function pksRunHash(n) {
    if (!pksOwn(PKS_RUN_HASHES, n)) PKS_RUN_HASHES[n] = pksHash(PKS_RUN_TABLES + JSON.stringify(pksLevel(n)));
    return PKS_RUN_HASHES[n];
  }

  function pksRunText(sim, cards) {
    var copy = {};
    var keys = Object.keys(sim);
    for (var i = 0; i < keys.length; i++) {
      if (keys[i] !== 'level' && keys[i] !== 'events') copy[keys[i]] = sim[keys[i]];
    }
    return JSON.stringify({ v: PKS_RUN_V, n: sim.n, hash: pksRunHash(sim.n), cards: cards, sim: copy });
  }

  function pksParseRun(text) {
    var raw;
    try {
      raw = JSON.parse(text);
    } catch (err) {
      return null;
    }
    if (!raw || raw.v !== PKS_RUN_V || !pksIsWhole(raw.n, 1, PKS_LEVELS) || raw.hash !== pksRunHash(raw.n)) return null;
    var sim = raw.sim;
    if (!pksRunCards(raw.cards) || !sim || !pksRunSound(sim, raw)) return null;
    sim.level = pksLevel(raw.n);
    sim.events = [];
    try {
      pksStep(JSON.parse(JSON.stringify(sim)));
    } catch (err) {
      return null;
    }
    return { n: raw.n, cards: raw.cards, sim: sim, time: sim.time };
  }

  function pksRunCards(cards) {
    if (!Array.isArray(cards) || cards.length < 1 || cards.length > PKS_MAX_LOADOUT) return false;
    for (var i = 0; i < cards.length; i++) {
      if (typeof cards[i] !== 'string' || !pksOwn(PKS_DEF, cards[i]) || cards.indexOf(cards[i]) !== i) return false;
    }
    return true;
  }

  function pksRunSound(sim, raw) {
    var i;
    if (sim.n !== raw.n || sim.status !== 'playing' || !sim.stats || typeof sim.stats !== 'object') return false;
    for (i = 0; i < PKS_RUN_LISTS.length; i++) {
      if (!Array.isArray(sim[PKS_RUN_LISTS[i]])) return false;
    }
    for (i = 0; i < PKS_RUN_COUNTS.length; i++) {
      if (typeof sim[PKS_RUN_COUNTS[i]] !== 'number' || !isFinite(sim[PKS_RUN_COUNTS[i]])) return false;
    }
    if (sim.breakers.length !== PKS_LANES || sim.cards.length !== raw.cards.length) return false;
    for (i = 0; i < sim.cards.length; i++) {
      if (!sim.cards[i] || sim.cards[i].id !== raw.cards[i]) return false;
    }
    return true;
  }

  function pksReadRun(storage) {
    var text;
    try {
      text = storage.getItem(PKS_RUN_KEY);
    } catch (err) {
      return { text: null, run: null, ok: false, error: err, newer: 0 };
    }
    return { text: text, run: text === null ? null : pksParseRun(text), ok: true, error: null, newer: pksNewerV(text, PKS_RUN_V) };
  }

  function pksPutRun(storage, text, expect) {
    try {
      var stored = storage.getItem(PKS_RUN_KEY);
      if (stored !== expect || pksNewerV(stored, PKS_RUN_V)) return { ok: false, lost: true, error: null };
      storage.setItem(PKS_RUN_KEY, text);
    } catch (err) {
      return { ok: false, lost: false, error: err };
    }
    return { ok: true, lost: false, error: null };
  }

  function pksDropRun(storage, expect) {
    try {
      var stored = storage.getItem(PKS_RUN_KEY);
      if ((expect === undefined || stored === expect) && !pksNewerV(stored, PKS_RUN_V)) storage.removeItem(PKS_RUN_KEY);
    } catch (err) {
      return false;
    }
    return true;
  }

  // ── src/ui-text.js ──

  // ── ui: the words of the page: names, refusals, results, the codex lines ──

  var PKS_CARD_NAMES = pksCardTable(function (d) { return d.name; }, 'Decommission');
  var PKS_LABEL_MAX = 10;
  var PKS_SHORT_NAMES = {
    proxy: 'Proxy', limiter: 'Limiter', patch: 'Patch', inspector: 'Inspector', sigdb: 'Sig DB', sinkhole: 'Sinkhole'
  };
  var PKS_CARD_SHORTS = pksCardTable(function (d) {
    return pksOwn(PKS_SHORT_NAMES, d.id) ? PKS_SHORT_NAMES[d.id] : d.name;
  }, 'Decom');
  var PKS_CARD_COSTS = pksCardTable(function (d) { return String(d.cost); }, 'free');
  var PKS_CARD_LABELS = pksCardTable(function (d) { return d.name + ', ' + d.cost + ' cycles'; }, 'Decommission, removes a defender');
  var PKS_CARD_HINTS = pksCardTable(function (d) {
    return d.name + ' (' + d.cost + ' cycles): ' + d.desc + ' Now pick a cell.';
  }, 'Decommission: pick a defender to remove. There is no refund.');
  var PKS_CARD_ARMS = pksCardTable(function (d) {
    return d.arm ? ', arms in ' + d.arm + ' s' : '';
  }, '');
  var PKS_THREAT_NAMES = pksThreatNames();
  var PKS_CODEX_ENEMIES = pksCodexEnemies();
  var PKS_CODEX_BOSSES = pksCodexBosses();
  var PKS_END_BEAT = 1.2;       // seconds between the end of a level and its result screen
  var PKS_NEWS_TIME = 10;       // seconds of play the news banner stays (unless a placement ends it)
  var PKS_LEAVE_TEXT = {
    leave: 'Leave this level? Progress in it is lost.',
    keep: 'Leave this level? It is saved: Resume on the level select picks it up again.',
    restart: 'Restart this level? Progress in it is lost.'
  };
  var PKS_LEAVE_YES = { leave: 'Leave', keep: 'Leave', restart: 'Restart' };
  var PKS_LEAVE_LABEL = {
    leave: 'Leave the level; its progress is lost',
    keep: 'Leave the level; it stays saved to resume',
    restart: 'Restart the level; its progress is lost'
  };
  var PKS_OVERTIME_SHOW = 60;
  var PKS_OVERTIME_MARKS = [60, 10];
  var PKS_RULE_NAMES = {
    express: 'Express', hot: 'Hot cells', rails: 'Rails', tunnels: 'Tunnels', blackout: 'Blackout', cross: 'Crossover',
    upkeep: 'Upkeep', outage: 'Outage', fog: 'Fog'
  };
  var PKS_RULE_ART = {
    express: 'tile-express', hot: 'tile-hot', rails: 'tile-rail', tunnels: 'tile-tunnel', blackout: 'fx-dark',
    cross: 'tile-cross-up', upkeep: 'icon-upkeep', outage: 'fx-outage', fog: 'fog'
  };
  var PKS_RULE_TEXT = {
    express: pksExpressText, hot: pksHotText, rails: pksRailsText, tunnels: pksTunnelsText, blackout: pksBlackoutText,
    cross: pksCrossText, upkeep: pksUpkeepText, outage: pksOutageText, fog: pksFogText
  };
